INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('nature', 'aseryn', 'aseryn', 'Aseryn', NULL, '{"nature":"aseryn","description":"Les Aseryns sont un peuple terrestre créé par Serathè avant les civilisations humaines historiques. Leur physiologie extrêmement rapide, leur sens électromagnétique et leur potentiel lié à la Foudre ne résument pas une civilisation ancienne, dispersée et politiquement diverse. Origine ou diaspora et Tradition des Treize sont des héritages culturels distincts, jamais des castes biologiques.","carte":"**ASERYN · NATURE** — une espèce créée par Serathè, humaine d''apparence, plus rapide de nerfs et de pensée.\n\n**Voilé (V)** : aucun modificateur.\n**Semi-Révélé (SR)** : +1 Agilité (+ modificateur d''Origine).\n**Révélé (R)** : +2 Agilité (+ modificateur d''Origine).\nCes bonus ne donnent jamais de PA en plus : l''Initiative les fixe.\n\n**Traits gratuits**\n- **Accelyr** (V/SR/R) : une langue parlée trop vite pour une oreille humaine. Aucun bonus chiffré ; communication éclair entre Aseryns.\n- **Physiologie aseryne** (V/SR/R) : vie de plusieurs siècles, nerfs et activité électrique supérieurs. Narratif ; aucune résistance universelle aux maladies, poisons ou fatigues.\n- **Sens électromagnétique** (SR/R, passif) : tu perçois les sources électromagnétiques marquées, les courants forts et les variations du champ. En te concentrant 1 PA : Esprit + Perception + 1d10e pour une direction, une distance approximative, la nature de la source. Ne lit aucune donnée ; blindage et brouillage le gênent.\n- **Potentiel foudroyant** : tout Aseryn peut apprendre la Foudre, avec un vrai enseignement (voir Dratyn). Les prodiges spontanés sont des PNJ.\n\n**Faiblesses** : aucune propre à la Nature.\n\n*Référence MJ — Variation de Vigueur* : quand une forme change la Vigueur, PV maximum et PV actuels varient de 2 × la variation. Une baisse ne fait pas passer sous 1 PV. **Correction** : si ce plancher a évité une perte, la hausse suivante n''ajoute pas les PV ainsi épargnés. (Avant, un Hyperboréen à 1 PV regagnait 2 PV à chaque aller-retour R → V → R.)\n\n**Gratuit aussi à la création** : l''Empreinte de ton Origine.\n\n---","traits_gratuits":[{"name":"Accelyr","access":"V/SR/R","effect":"Langue aseryne parlée à une vitesse que l’oreille et le cerveau humains ne suivent normalement pas."},{"name":"Physiologie aseryne","access":"V/SR/R","effect":"Longévité exceptionnelle et activité neuromusculaire rapide."},{"name":"Sens électromagnétique","access":"SR/R","effect":"Perçoit les sources et variations électromagnétiques significatives."}],"droits_acquis":"Les talents achetés avant les voies restent acquis ; les règles de voie valent pour les achats suivants (décision 20)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'aseryn', 'aseryn_routes_communes_tout_aseryn', 'Routes communes (tout Aseryn)', NULL, '{"nature":"aseryn","chemin":["Routes communes (tout Aseryn)"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'aseryn', 'aseryn_routes_communes_tout_aseryn_vivacite', 'Vivacité', NULL, '{"nature":"aseryn","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"note « le +1 Esquive de Réflexes défensifs reste utile » retirée. Ressort face à Éclair de colère (Angelus) : la Surcadence est nerveuse, décidée au début du round, sans ressource ; l''Angelus paie 3 Aura en Réaction. Voir question 2."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_routes_communes_aserynes_vivacite_aseryne_depart_fulgurant', 'Départ fulgurant', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, passif","activation":null,"texte_court":"+3 à ton Initiative pour l''ordre d''action dans les passes, jamais pour le nombre de PA.","texte_reference":"SR/R — Passif Après avoir déterminé normalement le nombre de PA du personnage, ajoutez +3 à son score d''Initiative uniquement pour déterminer son ordre d''action dans les passes. Ce bonus ne modifie jamais le nombre de PA obtenu.","lore":"La vivacité aseryne se voit d’abord dans l’instant où le personnage entre réellement dans l’action. Son système nerveux place sa décision plus tôt dans la séquence du combat, sans lui donner davantage de gestes qu’il n’en possède.","groupe_actuel":"Routes communes aserynes › Vivacité aseryne","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_routes_communes_aserynes_vivacite_aseryne_reflexe_impossible', 'Réflexe impossible', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R","activation":"Réaction gratuite · 1/round","texte_court":"une fois par round, une Défense active physique sans payer son PA, même Surpris. Les autres restent payantes ; une seule défense par attaque.","texte_reference":"Une fois par round, vous pouvez effectuer une Défense active physique sans payer son PA, même surpris. Les autres Défenses actives restent payantes ; vous devez pouvoir physiquement vous défendre.\n\nLe +1 Esquive de Réflexes défensifs reste utile si les deux talents sont possédés. Aucune seconde défense contre une même attaque. La défense gratuite n’est pas un gain de PA ajouté à la réserve.","lore":"Le réflexe aseryn devance la décision consciente et arrache une défense au danger.","groupe_actuel":"Routes communes aserynes › Vivacité aseryne","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_routes_communes_aserynes_vivacite_aseryne_surcadence_nerveuse', 'Surcadence nerveuse', NULL, '{"nature":"aseryn","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, 1/scène","activation":"Début du round · gratuit · 1/scène","texte_court":"au début d''un round, +1 PA pour toute action, même offensive. Pas de cumul avec un autre gain de PA ; plafond 4 PA ; aucune limite par round ou par scène n''est renouvelée.","texte_reference":"Une fois par scène, au début d’un round, gagnez 1 PA utilisable pour toute action, y compris offensive, sans coût d’activation. Il suit les passes normales et ne se cumule pas avec un autre gain direct de PA.\n\nLe choix se fait au début du round. Aucun renouvellement des limites par round ou par scène, dont l’attaque double d’Ambidextre. Plafond normal avec ce gain : 4 PA.","lore":"Le système nerveux libère une brève réserve de vitesse pour accomplir un geste décisif.","groupe_actuel":"Routes communes aserynes › Vivacité aseryne","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'aseryn', 'aseryn_routes_communes_tout_aseryn_esprit_fulgurant', 'Esprit fulgurant', NULL, '{"nature":"aseryn","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"deux talents au palier I."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_routes_communes_aserynes_esprit_fulgurant_traitement_accelere', 'Traitement accéléré', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1/scène","activation":null,"texte_court":"sur une tâche où le temps ne sert qu''à réfléchir ou comparer des informations déjà là, Prendre son temps sans délai.","texte_reference":"SR/R — 1/Scène Sur une tâche intellectuelle où le temps supplémentaire ne sert qu''à réfléchir, calculer ou comparer des informations déjà disponibles, l''Aseryn peut bénéficier de Prendre son temps sans consommer le délai supplémentaire.","lore":"Pour l’Aseryn, certaines longues réflexions ne sont longues que parce qu’un cerveau ordinaire traite les étapes l’une après l’autre. Le traitement accéléré comprime ce temps sans fournir la moindre information qui n’était pas déjà disponible.","groupe_actuel":"Routes communes aserynes › Esprit fulgurant","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_routes_communes_aserynes_esprit_fulgurant_pensee_parallele', 'Pensée parallèle', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, passif","activation":"Passif","texte_court":"tu surveilles activement tout en menant une tâche intellectuelle ou une conversation : ignore jusqu''à −3 dû au seul partage d''attention.","texte_reference":"Vous pouvez assurer une surveillance active tout en menant une tâche intellectuelle ou une communication. Ignorez jusqu’à −3 de malus provenant uniquement du partage de l’attention, sans obtenir d’action ni de concentration complexe supplémentaire.","lore":"Une partie de la pensée aseryne peut rester active en arrière-plan comme une note tenue. Compte, comparaison ou échange simple continue pendant l’action principale, sans jamais devenir une seconde concentration complexe dissimulée.","groupe_actuel":"Routes communes aserynes › Esprit fulgurant","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_routes_communes_aserynes_esprit_fulgurant_decision_fulgurante', 'Décision fulgurante', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1/scène ; requiert Traitement accéléré","activation":null,"texte_court":"après un échec non narratif à un test surtout d''Esprit, relance le d10e et garde le second.","texte_reference":"Prérequis : Traitement accéléré | SR/R — 1/Scène Après un échec non narratif à un test reposant principalement sur Esprit, relancez le 1d10e et conservez le second résultat.","lore":"L’Esprit fulgurant sait parfois retrouver la bonne voie après qu’une première conclusion vient de céder. L’échec intellectuel n’est pas effacé : il provoque une reprise immédiate du raisonnement avant que l’erreur ne se fige.","groupe_actuel":"Routes communes aserynes › Esprit fulgurant","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'aseryn', 'aseryn_routes_communes_tout_aseryn_perception_electromagnetique', 'Perception électromagnétique', NULL, '{"nature":"aseryn","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":"- **Socle (gratuit)** : Sens électromagnétique.","changements":"deux talents au palier II."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_routes_communes_aserynes_perception_electromagnetique_lecture_de_champ', 'Lecture de champ', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"en usage focalisé du Sens, +3 pour trouver la nature, l''intensité et l''origine probable d''un phénomène électromagnétique.","texte_reference":"SR/R Lors d''une utilisation focalisée du Sens électromagnétique, l''Aseryn bénéficie de +3 pour déterminer la nature, l''intensité et l''origine probable d''un phénomène électromagnétique.","lore":"Un champ électromagnétique possède intensité, direction et texture. L’Aseryn entraîné ne se contente plus de le sentir : il distingue suffisamment ses propriétés pour estimer quel type de source pourrait l’avoir produit.","groupe_actuel":"Routes communes aserynes › Perception électromagnétique","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_routes_communes_aserynes_perception_electromagnetique_cartographie_inductive', 'Cartographie inductive', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":null,"texte_court":"à 10 m environ, carte grossière des câbles actifs, machines alimentées et sources, à travers les obstacles ordinaires. Ni contenu ni fonction exacte.","texte_reference":"SR/R — 1 PA Dans un rayon d''environ 10 m, l''Aseryn peut dresser une cartographie grossière des câbles actifs, machines alimentées et principales sources électromagnétiques à travers des obstacles ordinaires. Il n''en lit ni le contenu ni la fonction exacte.","lore":"Les réseaux électriques dessinent une géographie invisible. En lisant l’induction à travers les obstacles ordinaires, l’Aseryn obtient le relief grossier des câbles actifs, machines alimentées et foyers électromagnétiques sans savoir encore ce qu’ils font.","groupe_actuel":"Routes communes aserynes › Perception électromagnétique","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_routes_communes_aserynes_perception_electromagnetique_signature_electrique', 'Signature électrique', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":1,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R","activation":"Passif","texte_court":"après étude d''une machine ou d''une source, tu mémorises sa signature et la reconnais plus tard si elle reste semblable. Ni pistage à distance, ni machine éteinte.","texte_reference":"SR/R Après avoir étudié une machine, un artefact alimenté ou une source énergétique, l''Aseryn peut mémoriser sa signature électromagnétique et la reconnaître ultérieurement si elle reste suffisamment similaire.\n\nPas de pistage à distance ni de localisation d’une machine éteinte par ce seul talent.","lore":"Une machine alimentée possède une signature aussi reconnaissable qu’un bruit de moteur. Après l’avoir étudiée, l’Aseryn peut la retrouver plus tard tant que ses caractéristiques électriques n’ont pas été profondément modifiées.","groupe_actuel":"Routes communes aserynes › Perception électromagnétique","statut_regle":"correction","changements":"Coût 1 → 2."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_routes_communes_aserynes_perception_electromagnetique_perception_neuromotrice', 'Perception neuromotrice', NULL, '{"nature":"aseryn","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R","activation":"Passif · bonus 1/round","texte_court":"à 3 m, si tu captes l''activité nerveuse ou électrique d''une cible dont tu connais la présence, tu te défends contre elle sans malus de vision ; une fois par round, +3 à une Défense active physique contre elle. Blindage et brouillage l''annulent.","texte_reference":"À 3 m maximum, si vous détectez l’activité nerveuse ou électromécanique d’une cible connue comme présente, vous défendez contre ses mouvements sans les malus dus au seul défaut de vision. Une fois par round, bénéficiez aussi de +3 à une Défense active physique contre cette cible.\n\nLe blindage, le brouillage ou l’absence de signal pertinent neutralisent le bénéfice. Il ne révèle ni identité ni Nature et n’autorise pas une défense autrement impossible.","lore":"Avant qu’un muscle ou un moteur ne bouge franchement, une activité électrique a souvent déjà commencé. À très courte portée, l’Aseryn lit ce prélude et peut défendre son corps contre un mouvement que ses yeux n’auraient pas encore eu le temps d’interpréter.","groupe_actuel":"Routes communes aserynes › Perception électromagnétique","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'aseryn', 'aseryn_origines_une_seule_empreinte_gratuite_puis_sa_voie', 'Origines (une seule ; Empreinte gratuite, puis sa voie)', NULL, '{"nature":"aseryn","chemin":["Origines (une seule ; Empreinte gratuite, puis sa voie)"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'aseryn', 'aseryn_origines_une_seule_empreinte_gratuite_puis_sa_voie_aerilien_neo_atlante_e', 'Aérilien / Néo-Atlante — Empreinte : Résonance d''Aèr', NULL, '{"nature":"aseryn","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"deux talents au palier I. Ressort face à Lecture occulte (Angelus, 1 Aura) : un jet d''Esprit sans ressource, nourri par l''héritage d''Aèr."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_origines_jouables_aerilien_neo_atlante_empreinte_resonance_d_aer_lecture_des_flux', 'Lecture des flux', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":null,"texte_court":"Esprit + Perception : la grande nature d''une manifestation (sort actif, rituel, objet imprégné, lieu saturé, portail…). Le DR précise, sans livrer l''auteur.","texte_reference":"SR/R — 1 PA Esprit + Perception permet de distinguer la grande nature d''une manifestation : sort actif, rituel, objet imprégné, lieu saturé, portail, etc. Le DR augmente la précision sans révéler automatiquement l''auteur ou tous les mécanismes.","lore":"Les flux magiques ont des comportements assez différents pour qu’un Aérilien entraîné en distingue les grandes catégories. Il reconnaît rituel, objet imprégné, portail ou lieu saturé sans recevoir pour autant le dossier complet de leur origine.","groupe_actuel":"Origines jouables › Aérilien / Néo-Atlante › Empreinte — Résonance d’Aèr","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_origines_jouables_aerilien_neo_atlante_empreinte_resonance_d_aer_memoire_de_resonance', 'Mémoire de résonance', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"après étude d''une signature magique perceptible, tu la reconnais plus tard, ou sa source, si elle n''a pas été profondément altérée.","texte_reference":"SR/R Après avoir étudié une signature magique directement perceptible, l''Aérilien peut reconnaître ultérieurement la même signature ou la même source si elle n''a pas été profondément altérée.","lore":"Une signature magique étudiée peut être mémorisée comme on retient une voix. Si la source n’a pas été profondément transformée, l’Aérilien reconnaît plus tard la même résonance même dans un contexte différent.","groupe_actuel":"Origines jouables › Aérilien / Néo-Atlante › Empreinte — Résonance d’Aèr","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_origines_jouables_aerilien_neo_atlante_empreinte_resonance_d_aer_ancrage_d_aer', 'Ancrage d''Aèr', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, Réaction, 1/scène","activation":null,"texte_court":"après un échec non narratif en Défense occulte contre un effet magique ou de Mageius, relance le d10e et garde le second.","texte_reference":"SR/R — Réaction — 1/Scène Après un échec non narratif à une défense occulte contre un effet explicitement magique ou lié à un Mageius, relancez le 1d10e et conservez le second résultat.","lore":"La résonance d’Aèr demeure chez certains Aéryliens comme un point d’ancrage face à la magie et au Mageius. Lorsqu’une défense occulte vient tout juste de céder, cet héritage permet à l’esprit de se replacer une fois dans son accord d’origine.","groupe_actuel":"Origines jouables › Aérilien / Néo-Atlante › Empreinte — Résonance d’Aèr","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'aseryn', 'aseryn_origines_une_seule_empreinte_gratuite_puis_sa_voie_mulien_empreinte_etinc', 'Mûlien — Empreinte : Étincelle psychique', NULL, '{"nature":"aseryn","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":"- **Socle (gratuit)** : Étincelle psychique.","changements":"deux talents au palier I. Ressorts face à l''Angelus : Effleurement ne détecte jamais un mensonge (Lecture superficielle, si) ; le Réseau transmet mots et images mais ni état ni position (le Nœud de conscience, si). Le rapport jugeait le Réseau trop fort face au Nœud : rien n''est changé, c''est un palier III payé 3 PTV."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_origines_jouables_mulien_empreinte_etincelle_psychique_telepathie_mulienne', 'Télépathie mûlienne', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, scène","activation":null,"texte_court":"l''Étincelle devient un dialogue avec une cible consentante, tant que portée et contact tiennent.","texte_reference":"SR/R — 1 PA — Scène L''Étincelle psychique devient une communication bidirectionnelle avec une cible consentante, tant que les conditions de portée et de contact mental sont maintenues.","lore":"Chez le Mûlien, la communication mentale devient réellement bidirectionnelle lorsqu’une cible accepte le lien. Deux consciences peuvent alors échanger directement, sans que cette proximité autorise l’une à fouiller automatiquement l’autre.","groupe_actuel":"Origines jouables › Mûlien › Empreinte — Étincelle psychique","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_origines_jouables_mulien_empreinte_etincelle_psychique_perception_mentale', 'Perception mentale', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":null,"texte_court":"Esprit + Perception : tu sens la présence approximative de consciences proches. Ni pensées, ni identité, ni plan exact.","texte_reference":"SR/R — 1 PA Esprit + Perception permet de sentir approximativement la présence de consciences proches. Le Talent ne révèle ni pensées ni identité et ne produit pas une cartographie exacte à travers les murs. Une dissimulation ou défense occulte peut s''y opposer.","lore":"L’Étincelle psychique ressent la présence de consciences proches comme des foyers dans un espace mental. Elle indique qu’un esprit est là sans dessiner son visage, son nom ni sa pensée sur une carte intérieure parfaite.","groupe_actuel":"Origines jouables › Mûlien › Empreinte — Étincelle psychique","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_origines_jouables_mulien_empreinte_etincelle_psychique_effleurement_de_pensee', 'Effleurement de pensée', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA ; requiert Télépathie mûlienne","activation":null,"texte_court":"Volonté + Maîtrise spirituelle contre Défense occulte : la pensée consciente dominante ou l''intention immédiate. Jamais souvenirs ni secrets.","texte_reference":"Prérequis : Télépathie mûlienne | SR/R — 1 PA Volonté + Maîtrise spirituelle contre la Défense occulte de la cible. En réussite, le Mûlien perçoit la pensée consciente dominante ou l''intention immédiate, jamais des souvenirs complets, des secrets profonds ou l''ensemble de l''esprit.","lore":"La télépathie mûlienne commence par un contact avec ce qui occupe déjà la conscience. Une pensée dominante ou une intention immédiate peut affleurer, mais la profondeur biographique d’un esprit reste derrière d’autres portes.","groupe_actuel":"Origines jouables › Mûlien › Empreinte — Étincelle psychique","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_origines_jouables_mulien_empreinte_etincelle_psychique_reseau_mulien', 'Réseau mûlien', NULL, '{"nature":"aseryn","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, scène ; requiert Télépathie mûlienne","activation":"1 PA · scène","texte_court":"relie jusqu''à cinq alliés consentants et toi, à 100 m : mots, images et perceptions partagés volontairement. Une barrière psychique ou la sortie de portée coupe le lien.","texte_reference":"Pour 1 PA, reliez jusqu’à cinq alliés consentants et vous-même dans un rayon de 100 m autour de vous, jusqu’à la fin de la scène. Le réseau transmet les mots, images et perceptions volontairement partagés, sans lecture forcée ni action gratuite.\n\nUne barrière psychique adaptée interrompt la liaison ; les participants sortis de portée perdent le lien. Ce talent ne transmet pas les connaissances ou les compétences complètes des membres.","lore":"Plusieurs esprits consentants peuvent former un réseau de conversation mentale. Chacun reste lui-même, mais paroles et signaux n’ont plus besoin d’air ni de gestes tant que le lien mûlien demeure ouvert entre eux.","groupe_actuel":"Origines jouables › Mûlien › Empreinte — Étincelle psychique","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'aseryn', 'aseryn_origines_une_seule_empreinte_gratuite_puis_sa_voie_hyperboreen_empreinte_', 'Hyperboréen — Empreinte : Corps hyperboréen', NULL, '{"nature":"aseryn","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"deux talents aux paliers I et II. **Correction** : Appuis du Nord ne se cumule pas avec la Trace hyperboréenne du Serathèen (même effet). Ressort de Percussion face à Impact de Gueburah (Angelus) : l''élan de 3 m, sans ressource."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_origines_jouables_hyperboreen_empreinte_corps_hyperboreen_detente_hyperboreenne', 'Détente hyperboréenne', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1/round","activation":"Déplacement · 1 PA · 1/round","texte_court":"ton Déplacement (5 + Athlétisme m) peut devenir un bond sans élan : toute la distance à l''horizontale, la moitié à la verticale. Réception praticable ; PA normal.","texte_reference":"Une fois par round, votre Déplacement peut devenir un bond sans élan couvrant votre distance normale horizontalement, ou sa moitié verticalement. Une réception praticable reste nécessaire ; le Déplacement coûte son PA normal.\n\nLa distance normale est 5 + Athlétisme mètres. Le talent ne donne ni vol ni déplacement gratuit et n’annule pas les dangers particuliers du point de réception.","lore":"Le corps hyperboréen convertit son élan interne en un bond dépassant les possibilités humaines.","groupe_actuel":"Origines jouables › Hyperboréen › Empreinte — Corps hyperboréen","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_origines_jouables_hyperboreen_empreinte_corps_hyperboreen_appuis_du_nord', 'Appuis du Nord', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"+3 contre une saisie, un renversement ou un déplacement physique forcé.","texte_reference":"SR/R +3 pour résister à une saisie, un renversement ou un déplacement physique forcé.","lore":"Le corps hyperboréen sait rendre sa masse utile. Lorsqu’on tente de le saisir, le renverser ou le pousser, ses appuis se placent avec la certitude d’un peuple habitué à tenir sur des terres qui pardonnent peu les chutes.","groupe_actuel":"Origines jouables › Hyperboréen › Empreinte — Corps hyperboréen","statut_regle":"correction","changements":"deux talents aux paliers I et II. **Correction** : Appuis du Nord ne se cumule pas avec la Trace hyperboréenne du Serathèen (même effet). Ressort de Percussion face à Impact de Gueburah (Angelus) : l''élan de 3 m, sans ressource."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_origines_jouables_hyperboreen_empreinte_corps_hyperboreen_percussion', 'Percussion', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1/round","activation":null,"texte_court":"après au moins 3 m parcourus avant une attaque de mêlée réussie : +2 DGT, ou la cible recule de 2 m.","texte_reference":"R — 1/round Après avoir volontairement parcouru au moins 3 m avant une attaque de mêlée réussie, choisissez : +2 DGT, ou repousser la cible de 2 m si sa morphologie et la situation le permettent.","lore":"Un Hyperboréen qui prend réellement son élan peut transformer la course en percussion. Le choc sert alors soit à approfondir l’impact, soit à déplacer l’adversaire comme une masse rencontrée par une autre lancée à pleine vitesse.","groupe_actuel":"Origines jouables › Hyperboréen › Empreinte — Corps hyperboréen","statut_regle":"correction","changements":"deux talents aux paliers I et II. **Correction** : Appuis du Nord ne se cumule pas avec la Trace hyperboréenne du Serathèen (même effet). Ressort de Percussion face à Impact de Gueburah (Angelus) : l''élan de 3 m, sans ressource."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_origines_jouables_hyperboreen_empreinte_corps_hyperboreen_reflexe_de_duel', 'Réflexe de duel', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1/round","activation":"1/round","texte_court":"après une Défense active réussie contre une mêlée, l''agresseur a −3 en Défense contre ta prochaine attaque de mêlée avant la fin du round suivant.","texte_reference":"Une fois par round, après une Défense active réussie contre une attaque de mêlée, l’agresseur subit −3 à sa Défense contre votre prochaine attaque de mêlée dirigée contre lui, avant la fin du round suivant. Cette attaque reste payante et cet avantage ne se cumule pas avec lui-même.","lore":"Une parade ou une esquive réussie dévoile immédiatement une ouverture dans la garde adverse.","groupe_actuel":"Origines jouables › Hyperboréen › Empreinte — Corps hyperboréen","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_origines_jouables_hyperboreen_empreinte_corps_hyperboreen_exploit_physique', 'Exploit physique', NULL, '{"nature":"aseryn","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, 1/scène","activation":null,"texte_court":"après un échec non narratif à un test surtout physique, relance le d10e et garde le second.","texte_reference":"SR/R — 1/Scène Après un échec non narratif à un test reposant principalement sur des capacités physiques, relancez le 1d10e et conservez le second résultat.","lore":"Dans l’urgence physique, l’héritage hyperboréen peut offrir une seconde tentative là où le corps venait d’échouer. Force, coordination ou endurance retrouvent momentanément l’exploit que la première exécution n’avait pas réussi à produire.","groupe_actuel":"Origines jouables › Hyperboréen › Empreinte — Corps hyperboréen","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'aseryn', 'aseryn_origines_une_seule_empreinte_gratuite_puis_sa_voie_lemurian_empreinte_her', 'Lémurian — Empreinte : Héritage nymphal', NULL, '{"nature":"aseryn","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"deux talents aux paliers I et II. Une carte par élément : le joueur ne lit que sa ligne. **Correction** : « en réussite elle est repoussée » (Air) précisé en « si tu l''emportes ». Façonnage et Manifestation restent séparés (manipuler l''existant / produire) : les fusionner baisserait un coût. Voir question 2 pour le Corps de pierre."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_origines_jouables_lemurian_empreinte_heritage_nymphal_sens_elementaire', 'Sens élémentaire', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"tu perçois avec précision la présence, le mouvement et les perturbations de ton élément à proximité.","texte_reference":"SR/R L''Aseryn perçoit avec précision la présence, le mouvement et les perturbations de son élément à proximité, dans les limites naturelles de ce que l''élément peut transmettre.","lore":"Un Lémurian sent son élément par les variations qu’il transporte. Mouvement de l’air, courant de l’eau, tension du sol ou chaleur du feu deviennent une perception supplémentaire limitée par la manière dont le milieu lui-même peut transmettre l’information.","groupe_actuel":"Origines jouables › Lémurian › Empreinte — Héritage nymphal","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_origines_jouables_lemurian_empreinte_heritage_nymphal_faconnage_nymphal', 'Façonnage nymphal', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA sous pression","activation":null,"texte_court":"tu manipules une petite quantité de ton élément déjà présent, pour un usage utile et non dommageable.","texte_reference":"SR/R — 1 PA sous pression L''Aseryn peut manipuler une quantité modeste de son élément déjà présent pour un usage utilitaire et non directement dommageable.","lore":"Le Façonnage nymphal travaille avec l’élément déjà présent. L’Aseryn le rassemble, le déplace ou le modèle pour un usage concret, révélant une parenté avec le milieu plutôt qu’une simple télékinésie déguisée.","groupe_actuel":"Origines jouables › Lémurian › Empreinte — Héritage nymphal","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_origines_jouables_lemurian_empreinte_heritage_nymphal_manifestation_elementaire', 'Manifestation élémentaire', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA","activation":null,"texte_court":"tu produis une petite quantité de ton élément, pour un usage utile. Pas une attaque.","texte_reference":"R — 1 PA L''Aseryn peut produire une quantité limitée de son élément pour un usage utilitaire. Ce Talent n''est pas, à lui seul, une attaque.","lore":"La Manifestation permet d’appeler une petite quantité de l’élément même quand le décor n’en offre pas assez. La création reste modeste et utile : lumière, eau, souffle ou matière élémentaire au service d’une action plutôt qu’une attaque implicite.","groupe_actuel":"Origines jouables › Lémurian › Empreinte — Héritage nymphal","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_origines_jouables_lemurian_empreinte_heritage_nymphal_corps_accorde', 'Corps accordé', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R","activation":null,"texte_court":"selon l''élément, table ci-dessous.","texte_reference":"R Air — Corps des hauteurs : Les chutes ordinaires ne causent normalement plus de dégâts tant que l’Aseryn est conscient et dispose d’un minimum d’espace pour se stabiliser. Un Déplacement peut devenir un grand bond soutenu permettant de franchir un vide ou de gagner/perdre fortement de l’altitude ; il doit terminer sur un support réel. Ce n’est jamais du vol stationnaire. Eau — Corps amphibie : L’Aseryn respire indéfiniment dans l’eau, voit et agit normalement sous l’eau, supporte les pressions naturelles correspondant à des profondeurs où un humain ne pourrait pas fonctionner et se déplace sans les pénalités ordinaires d’un corps humain. Les environnements surnaturels ou abyssaux peuvent toujours le menacer. Terre — Corps de pierre : En R : Armure corporelle 2 contre les dommages matériels. Une force physique humaine ordinaire ne suffit normalement pas à le renverser ou à le déplacer contre sa volonté s’il est solidement appuyé au sol. Feu — Corps incandescent : Le corps supporte sans dommage les flammes ordinaires, la chaleur naturelle extrême et la fumée/chaleur produite directement par son propre feu nymphal. Il reçoit Réduction 2 [Feu] contre les dégâts principalement thermiques ou de feu ; les attaques surnaturelles ou armes suffisamment puissantes restent capables de le blesser.","lore":"L’héritage nymphal n’est pas une décoration élémentaire mais une adaptation du corps à son élément. Air, eau, terre ou feu modifient respiration, appuis, résistance et manière d’habiter un milieu comme s’il avait toujours été naturel.","groupe_actuel":"Origines jouables › Lémurian › Empreinte — Héritage nymphal","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_origines_jouables_lemurian_empreinte_heritage_nymphal_dechainement_nymphal', 'Déchaînement nymphal', NULL, '{"nature":"aseryn","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 1/scène","activation":"2 PA · 1/scène","texte_court":"selon l''élément, table ci-dessous.","texte_reference":"R — 2 PA — 1/Scène Air — Front de tempête : Cône d’environ 10 m. Chaque cible exposée oppose sa Défense physique ; en réussite elle est repoussée jusqu’à environ 5 m selon masse et terrain et peut être Renversée si approprié. Fumées, gaz, poussières et flammes ordinaires non protégés sont dispersés. Pas de dégâts automatiques. Eau — Marée suspendue : À 20 m maximum, une zone de 4 m de rayon est saturée d’eau en mouvement jusqu’à la fin de la scène. Les flammes ordinaires sont éteintes ; la traverser consomme deux fois plus de distance de mouvement et les tirs non adaptés qui la traversent subissent −3. Pas de noyade automatique ni de cumul de plusieurs exemplaires de cette gêne. Terre — Soulèvement tellurique : Sur un support minéral connecté, créer pour la scène un couvert total de quelques mètres, un fossé/obstacle, une rampe/plateforme, fermer brutalement une ouverture terrestre ou soulever une petite zone pour Renverser ses occupants. Ne détruit pas automatiquement un bâtiment et ne manipule pas une structure entière hors échelle. Feu — Brasier primordial : Zone d’environ 4 m de rayon, portée courte/moyenne. Attaque surnaturelle directe DGT 8, Incendiaire ; une Altération appropriée peut provoquer Enflammé. Pas de second effet gratuit. L’héritage lémurian s’étend aux quatre grands éléments : Air, Eau, Terre et Feu.","lore":"Quand l’héritage lémurian se déchaîne, l’élément cesse d’être utilitaire et transforme le terrain. Tempête, masse d’eau, soulèvement minéral ou brasier expriment chacun la même idée : laisser le milieu agir à l’échelle d’une scène entière.","groupe_actuel":"Origines jouables › Lémurian › Empreinte — Héritage nymphal","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'aseryn', 'aseryn_origines_une_seule_empreinte_gratuite_puis_sa_voie_seratheen_empreinte_sa', 'Serathèen — Empreinte : Sang mêlé', NULL, '{"nature":"aseryn","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"deux talents au palier I. Prérequis de Mosaïque (Héritage éveillé, livre V6) rétabli : il levait l''incohérence signalée par le rapport. Le rapport proposait de fusionner Atavisme et Héritage : refusé (baisse de coût)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_origines_jouables_seratheen_empreinte_sang_mele_atavisme_marque', 'Atavisme marqué', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"passif","activation":null,"texte_court":"une de tes Traces devient l''Empreinte complète de son Origine, sans le bonus d''Attribut.","texte_reference":"Passif Choisissez l''une de vos Traces. Elle devient la Signature complète de l''Origine correspondante, sans accorder son bonus d''Attribut : Aérilienne = Résonance d''Aèr + Acclimatation arcanique ; Mûlienne = Étincelle psychique + Présence mentale ; Hyperboréenne = Corps hyperboréen ; Lémurienne = Héritage nymphal complet.","lore":"Le sang serathèen peut laisser une lignée ancestrale remonter avec une netteté inhabituelle. Une Trace mineure devient assez forte pour reproduire la véritable Signature d’une Origine, sans réécrire pour autant toute la constitution du personnage.","groupe_actuel":"Origines jouables › Serathèen › Empreinte — Sang mêlé","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_origines_jouables_seratheen_empreinte_sang_mele_sang_pluriel', 'Sang pluriel', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"passif, une fois","activation":null,"texte_court":"une troisième Trace mineure.","texte_reference":"Passif — une seule fois Gagnez une troisième Trace ancestrale mineure différente.","lore":"Certains sangs mêlés portent encore une troisième rumeur ancestrale. Elle reste légère, simple Trace supplémentaire dans un organisme dont l’histoire familiale refuse décidément de se laisser réduire à deux branches.","groupe_actuel":"Origines jouables › Serathèen › Empreinte — Sang mêlé","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_origines_jouables_seratheen_empreinte_sang_mele_heritage_eveille', 'Héritage éveillé', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"passif ; requiert Atavisme marqué","activation":null,"texte_court":"tu peux acheter la voie de l''Origine de cette Trace comme si tu en étais. Rien de gratuit.","texte_reference":"Prérequis : Atavisme marqué | Passif Le personnage peut acheter les Talents d''Origine associés à la Trace choisie comme s''il appartenait à cette Origine. Il ne gagne aucun Talent gratuitement.","lore":"Une Trace devenue pleinement éveillée n’est plus seulement souvenir biologique. Le Serathèen peut désormais apprendre les techniques qui appartiennent à cette lignée comme un héritier tardif revenu réclamer une tradition longtemps restée silencieuse.","groupe_actuel":"Origines jouables › Serathèen › Empreinte — Sang mêlé","statut_regle":"correction","changements":"deux talents au palier I. Prérequis de Mosaïque (Héritage éveillé, livre V6) rétabli : il levait l''incohérence signalée par le rapport. Le rapport proposait de fusionner Atavisme et Héritage : refusé (baisse de coût)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_origines_jouables_seratheen_empreinte_sang_mele_mosaique_ancestrale', 'Mosaïque ancestrale', NULL, '{"nature":"aseryn","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"passif ; requiert Héritage éveillé","activation":"Passif","texte_court":"une seconde Trace devient Empreinte complète et ouvre la voie de son Origine, sans racheter Atavisme ni Héritage. Les bonus équivalents ne se doublent pas.","texte_reference":"Une seconde Trace devient une Signature complète, sans bonus d’Attribut, et ouvre les talents de cette Origine. Aucun nouvel achat d’Atavisme marqué ou d’Héritage éveillé n’est exigé pour cette seconde lignée.\n\nLes talents de la nouvelle Origine restent à acheter. Les deux Signatures ne doublent pas un même bonus équivalent.","lore":"Deux héritages peuvent pleinement s’exprimer dans une même ascendance sans fusionner leurs origines.","groupe_actuel":"Origines jouables › Serathèen › Empreinte — Sang mêlé","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'aseryn', 'aseryn_traditions_des_treize_cumulables_sans_taxe', 'Traditions des Treize (cumulables, sans taxe)', NULL, '{"nature":"aseryn","chemin":["Traditions des Treize (cumulables, sans taxe)"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'aseryn', 'aseryn_traditions_des_treize_cumulables_sans_taxe_athegos_le_seigneur', 'Athegos, le Seigneur', NULL, '{"nature":"aseryn","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun. Le rapport proposait de fusionner Prendre la tête avec Synchronisation (Angelus) : refusé. Ressort propre : un ordre parlé, que les alliés doivent entendre, sans ressource."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_athegos_le_seigneur_ordre_fulgurant', 'Ordre fulgurant', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R, 1/round","activation":null,"texte_court":"tu fournis une Assistance +2 en combat à un allié que tu peux conseiller et avec qui tu communiques (Compétence requise). Entre Aseryns, en Accelyr.","texte_reference":"V/SR/R — 1/round L''Aseryn peut fournir une Assistance +2 en combat, normalement interdite, à un allié qu''il peut réellement conseiller et avec lequel il peut communiquer. Les conditions normales d''Assistance restent valables, notamment la Compétence minimale requise. Avec un autre Aseryn, l''ordre peut être transmis en Accelyr.","lore":"Athegos commande au rythme de la bataille. Une consigne lancée au bon moment devient une véritable aide tactique même au milieu des échanges, parce qu’elle s’adresse à un allié capable de comprendre et d’exécuter ce conseil.","groupe_actuel":"Traditions des Treize › Athegos — le Seigneur","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_athegos_le_seigneur_prendre_la_tete', 'Prendre la tête', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"1/scène","activation":"1/scène","texte_court":"dans une passe où tu agis, jusqu''à deux alliés qui n''ont pas agi le font juste après toi, même avant des adversaires. Ils doivent entendre l''ordre, payer leur action et perdent leur ancien emplacement.","texte_reference":"Une fois par scène, dans une passe où vous agissez, jusqu’à deux alliés qui n’ont pas encore agi peuvent agir immédiatement après vous, même si des adversaires auraient dû agir avant eux. Chacun dépense son PA et perd son ancien emplacement dans cette passe.\n\nLes alliés doivent pouvoir recevoir l’ordre et disposer d’une action dans cette passe. Aucune action supplémentaire ni transfert entre passes.","lore":"Le commandement impose aux alliés un tempo commun avant que l’adversaire ne reprenne l’initiative.","groupe_actuel":"Traditions des Treize › Athegos — le Seigneur","statut_regle":"correction","changements":"aucun. Le rapport proposait de fusionner Prendre la tête avec Synchronisation (Angelus) : refusé. Ressort propre : un ordre parlé, que les alliés doivent entendre, sans ressource."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_athegos_le_seigneur_une_seule_decision', 'Une seule décision', NULL, '{"nature":"aseryn","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"1 PA, 1/scène","activation":null,"texte_court":"un plan bref transmis à jusqu''à trois alliés consentants : +2 (Assistance) à leur première action nécessaire au plan avant ton prochain round.","texte_reference":"1 PA — 1/Scène Athegos transmet un plan bref à jusqu''à trois alliés consentants. Chacun reçoit +2 à sa première action directement nécessaire à ce plan avant le début du prochain round d''Athegos. Ce bonus est une Assistance.","lore":"Un plan bref transmis par Athegos devient une décision commune plutôt qu’une suite d’initiatives concurrentes. Chacun sait quelle première action sert réellement l’objectif partagé avant que la scène ne recommence à se disperser.","groupe_actuel":"Traditions des Treize › Athegos — le Seigneur","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'aseryn', 'aseryn_traditions_des_treize_cumulables_sans_taxe_sundosia_l_aventuriere', 'Sundosia, l''Aventurière', NULL, '{"nature":"aseryn","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"**correction** — « devient passive » renvoyait à une version disparue ; le talent est écrit passif (site). Le livre le donnait 1/scène."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_sundosia_l_aventuriere_toujours_une_issue', 'Toujours une issue', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"1/scène","activation":null,"texte_court":"quand une approche se révèle impraticable, demande au MJ quelle autre possibilité réaliste tu peux tenter tout de suite avec ce que tu sais ou perçois. Rien n''est inventé.","texte_reference":"1/Scène Quand une approche, un accès ou un itinéraire vient de se révéler impraticable, le joueur peut demander au MJ quelle autre possibilité réaliste peut immédiatement être tentée avec ce que le personnage perçoit ou sait. Le Talent n''invente aucun passage qui n''existe pas.","lore":"Une voie qui se ferme n’épuise pas l’esprit de l’Aventurière. Sundosia balaie ce qu’elle voit et sait pour retrouver l’autre option réellement disponible, sans faire apparaître une porte secrète que le lieu n’a jamais contenue.","groupe_actuel":"Traditions des Treize › Sundosia — l’Aventurière","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_sundosia_l_aventuriere_improvisation_d_aventurier', 'Improvisation d''aventurier', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"passif","activation":"Passif","texte_court":"ignore jusqu''à −3 dû au détournement crédible d''un objet, d''un véhicule ou du décor, y compris pour attaquer. Ni outil absent, ni dégâts en plus.","texte_reference":"L’annulation de jusqu’à −3 de malus dus au détournement crédible d’un objet, véhicule ou élément du décor devient passive. Elle peut s’appliquer à un usage offensif réalisable, mais ne crée ni outil absent, ni arme supérieure, ni dégâts supplémentaires.","lore":"Sundosia a survécu assez longtemps pour voir qu’un objet utile n’est pas toujours utilisé comme son fabricant l’avait prévu. L’improvisation crédible cesse d’être maladroite lorsque l’Aventurière trouve immédiatement la prise, l’angle ou l’usage de circonstance.","groupe_actuel":"Traditions des Treize › Sundosia — l’Aventurière","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_sundosia_l_aventuriere_s_adapter_ou_mourir', 'S''adapter ou mourir', NULL, '{"nature":"aseryn","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"1/scène","activation":"1/scène","texte_court":"après un échec non narratif face à une situation nouvelle, nomme la difficulté apprise : jusqu''à la fin de la scène, les actions qui l''affrontent baissent d''un niveau de Difficulté.","texte_reference":"Une fois par scène, après un échec non narratif dû à une situation ou un environnement nouveau, identifiez la difficulté apprise. Jusqu’à la fin de la scène, les actions directement confrontées à cette même difficulté bénéficient d’une réduction d’un niveau de Difficulté.\n\nL’échec initial reste acquis. Ce n’est pas une réduction de tous les jets dans un nouveau lieu et les réductions génériques équivalentes ne s’empilent pas.","lore":"Le premier échec dans un milieu réellement nouveau devient une leçon accélérée. Sundosia assimile ce que l’environnement vient de lui apprendre et adapte la tentative suivante au lieu de répéter le comportement qui a déjà montré ses limites.","groupe_actuel":"Traditions des Treize › Sundosia — l’Aventurière","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'aseryn', 'aseryn_traditions_des_treize_cumulables_sans_taxe_caendis_le_protecteur', 'Caendis, le Protecteur', NULL, '{"nature":"aseryn","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_caendis_le_protecteur_interposition', 'Interposition', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"Réaction, 1 PA","activation":null,"texte_court":"un allié à 2 m est visé par une attaque physique : tu te places sur la trajectoire et deviens la cible.","texte_reference":"Réaction — 1 PA Lorsqu''un allié situé à 2 m maximum est directement ciblé par une attaque physique, Caendis peut se déplacer dans la trajectoire si cela est matériellement possible et devenir la cible de l''attaque.","lore":"L’interposition de Caendis est un choix physique, pas une aura abstraite. Il se jette réellement entre l’attaque et son allié et accepte que la menace change de cible parce que son propre corps occupe désormais la trajectoire.","groupe_actuel":"Traditions des Treize › Caendis — le Protecteur","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_caendis_le_protecteur_garde_rapprochee', 'Garde rapprochée', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"1/round ; requiert Interposition","activation":null,"texte_court":"+3 à une Défense active faite en protégeant directement quelqu''un.","texte_reference":"Prérequis : Interposition | 1/round +3 à une Défense active effectuée alors que Caendis protège directement quelqu''un d''autre.","lore":"Protéger quelqu’un change la manière dont Caendis défend. Sa garde cesse d’être centrée sur sa propre survie et devient plus précise, parce que chaque parade sait exactement quel corps elle refuse de laisser atteindre.","groupe_actuel":"Traditions des Treize › Caendis — le Protecteur","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_caendis_le_protecteur_aucun_ne_passera', 'Aucun ne passera', NULL, '{"nature":"aseryn","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"1/scène ; requiert Garde rapprochée","activation":null,"texte_court":"en déclenchant une Interposition, tu peux en faire deux de plus sans leur PA jusqu''au début de ton prochain round. Défenses actives payantes.","texte_reference":"Prérequis : Garde rapprochée | 1/Scène Lorsqu''il utilise Interposition, Caendis peut déclarer ce Talent. Jusqu''au début de son prochain round, il peut effectuer jusqu''à deux Interpositions supplémentaires sans payer leur coût en PA, à condition que chaque déplacement reste physiquement possible. Les Défenses actives éventuelles coûtent toujours leurs PA normaux.","lore":"Caendis peut devenir une ligne que l’adversaire doit traverser plusieurs fois. Après la première interposition, le Protecteur garde son corps prêt à reprendre la trajectoire d’autres attaques tant que ses jambes peuvent réellement atteindre ceux qu’il couvre.","groupe_actuel":"Traditions des Treize › Caendis — le Protecteur","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'aseryn', 'aseryn_traditions_des_treize_cumulables_sans_taxe_cairiah_l_architecte', 'Cairiah, l''Architecte', NULL, '{"nature":"aseryn","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"exceptions de cumul raccourcies."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_cairiah_l_architecte_il_de_structure', 'Œil de structure', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"passif","activation":"Passif · exploitation 1/scène","texte_court":"après examen, tu vois supports, fragilités et consolidations possibles ; +3 pour les défauts cachés. Une fois par scène, +3 au premier test pour forcer, saboter ou consolider grâce à une faiblesse repérée. Pas de cumul sur un même test.","texte_reference":"Après examen, vous identifiez les supports, fragilités et possibilités de consolidation d’une structure, avec +3 pour les défauts cachés. Une fois par scène, exploiter une faiblesse identifiée donne +3 au premier test pour forcer, saboter ou consolider cette structure.\n\nUne observation ou un examen réellement possible reste requis. Les deux bonus ne s’additionnent pas sur le même test et aucun effondrement n’est garanti sans moyens matériels adaptés.","lore":"Une structure raconte comment elle tient debout. Cairiah lit supports, charges, zones faibles et possibilités de consolidation comme d’autres lisent une carte, sans inventer ce qu’un défaut réellement caché ne laisse pas voir.","groupe_actuel":"Traditions des Treize › Cairiah — l’Architecte","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_cairiah_l_architecte_fortification', 'Fortification', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"quelques minutes","activation":"Quelques minutes de préparation","texte_court":"avec matériaux et outils, tes couverts aménagés donnent +6 Défense au lieu de +3 dans les directions protégées. Ils restent contournables et destructibles.","texte_reference":"Après quelques minutes de travail avec les matériaux et outils nécessaires, vos barricades et couverts aménagés offrent +6 Défense au lieu de +3 contre les directions réellement protégées. Ce bonus remplace celui du couvert partiel et ne s’y ajoute pas.\n\nPas de construction instantanée ni de matériau créé. Le couvert reste physique, contournable et destructible ; il ne devient pas un couvert total.","lore":"Cairiah transforme un lieu en position plutôt qu’en simple décor. Matériaux, angles et accès sont organisés selon la menace prévue, produisant une fortification réelle qui vaut parce qu’elle a été construite avant que le combat n’arrive.","groupe_actuel":"Traditions des Treize › Cairiah — l’Architecte","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_cairiah_l_architecte_position_maitresse', 'Position maîtresse', NULL, '{"nature":"aseryn","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"30 minutes ; requiert Fortification","activation":"30 minutes de préparation","texte_court":"jusqu''à trois ouvrages fortifiés ; jusqu''à trois défenseurs briefés gagnent +3 à leur première Défense active de chaque round tant qu''ils tiennent la position. Une position à la fois.","texte_reference":"Après trente minutes de préparation, jusqu’à trois ouvrages bénéficient de Fortification et jusqu’à trois défenseurs briefés gagnent +3 à leur première Défense active de chaque round lorsqu’ils défendent cette position. Une seule position bénéficie à la fois de cette coordination.\n\nLes ouvrages ordinaires ne disparaissent pas lors d’un changement de position. Le bonus de coordination cesse hors de la position et ne se cumule pas avec une autre circonstance défensive équivalente ; les PA des Défenses actives restent dus.","lore":"Avec du temps, l’Architecte ne prépare plus un seul abri mais un petit système défensif. Plusieurs ouvrages se complètent et donnent au terrain une logique de circulation, de protection et de repli pensée comme un ensemble.","groupe_actuel":"Traditions des Treize › Cairiah — l’Architecte","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'aseryn', 'aseryn_traditions_des_treize_cumulables_sans_taxe_eydreas_le_chercheur', 'Eydreas, le Chercheur', NULL, '{"nature":"aseryn","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"fréquence du site (1/scène ; livre : 1/scénario). Ressort face à Vision sereine (Angelus) : deux explications à départager, en équipe, sans ressource ; l''Angelus confronte son propre plan pour 3 Aura."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_eydreas_le_chercheur_hypothese_adverse', 'Hypothèse adverse', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"1/scène","activation":null,"texte_court":"après une hypothèse fondée sur des indices, demande : « Quel élément déjà observé cadre le moins avec elle ? » Le MJ désigne un détail existant, s''il y en a un.","texte_reference":"1/Scène Après avoir construit une hypothèse à partir d''indices, le joueur peut demander : « Quel élément que j''ai déjà observé cadre le moins bien avec mon hypothèse ? » Le MJ désigne un détail existant s''il y en a un ; aucune information nouvelle n''est créée.","lore":"Le Chercheur combat sa propre hypothèse en demandant quelle observation résiste le mieux à son modèle. Le détail gênant redevient visible au lieu d’être inconsciemment repoussé parce qu’il compliquait une explication séduisante.","groupe_actuel":"Traditions des Treize › Eydreas — le Chercheur","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_eydreas_le_chercheur_reprendre_le_raisonnement', 'Reprendre le raisonnement', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"1/scène","activation":"1/scène","texte_court":"après un test réussi d''analyse, d''enquête ou de diagnostic, +1 DR pour la précision des conclusions (max 5).","texte_reference":"Une fois par scène, après un test réussi d’analyse, d’enquête ou de diagnostic intellectuel, comptez un DR supplémentaire pour la précision des conclusions, jusqu’à DR 5. Cela ne fournit aucune preuve absente et n’augmente ni dégâts ni PV soignés.","lore":"Eydreas pousse une conclusion juste jusqu’au détail qui lui donne toute sa valeur.","groupe_actuel":"Traditions des Treize › Eydreas — le Chercheur","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_eydreas_le_chercheur_detruire_la_fausse_certitude', 'Détruire la fausse certitude', NULL, '{"nature":"aseryn","cout":3,"cout_actuel":2,"palier":"III","porte":null,"palier_double":null,"acces":"1/scène","activation":"1/scène","texte_court":"le MJ indique une vérification concrète qui départage deux explications. Ceux qui l''exécutent gagnent +3 aux tests nécessaires.","texte_reference":"Une fois par scène, à partir des indices disponibles, le MJ indique une vérification concrète permettant de départager deux explications, lorsqu’une telle vérification existe. Ceux qui exécutent ce protocole bénéficient de +3 aux tests directement nécessaires à cette vérification.\n\nPas de preuve créée ni de résultat révélé à l’avance. Un seul protocole préparé actif ; le même test ne reçoit pas plusieurs fois ce bonus.","lore":"Le doute devient un protocole précis pour confronter deux explications aux faits.","groupe_actuel":"Traditions des Treize › Eydreas — le Chercheur","statut_regle":"correction","changements":"Coût 2 → 3."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'aseryn', 'aseryn_traditions_des_treize_cumulables_sans_taxe_seryn_l_artisane', 'Seryn, l''Artisane', NULL, '{"nature":"aseryn","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_seryn_l_artisane_main_de_seryn', 'Main de Seryn', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"1/scène","activation":null,"texte_court":"pour fabriquer, réparer ou modifier ce que tu maîtrises, Prendre son temps sans délai.","texte_reference":"1/Scène Pour fabriquer, réparer ou modifier quelque chose que Seryn maîtrise réellement, elle peut bénéficier de Prendre son temps sans consommer le délai supplémentaire.","lore":"Les mains de l’Artisane savent retrouver immédiatement le calme d’un atelier, même lorsque le temps manque. Pour un travail réellement maîtrisé, Seryn bénéficie de la précision d’une longue préparation sans obtenir des heures qui n’existent pas.","groupe_actuel":"Traditions des Treize › Seryn — l’Artisane","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_seryn_l_artisane_adaptation_de_terrain', 'Adaptation de terrain', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"quelques minutes","activation":null,"texte_court":"tu modifies un équipement connu contre une contrainte précise (ergonomie, étanchéité, alimentation, équilibre…) : pour la scène, il ignore jusqu''à −3 dû à cette contrainte.","texte_reference":"Préparation de quelques minutes Seryn modifie un équipement connu pour répondre à une contrainte précise : ergonomie, montage, étanchéité, alimentation, équilibre, protection d''une partie fragile, etc. Jusqu''à la fin de la scène, l''équipement ignore jusqu''à -3 de malus provenant de cette contrainte.","lore":"Seryn adapte l’objet à la contrainte plutôt que d’exiger du monde qu’il soit commode. Quelques modifications ciblées d’ergonomie, d’étanchéité, de montage ou de protection rendent un équipement familier plus apte à la scène présente.","groupe_actuel":"Traditions des Treize › Seryn — l’Artisane","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_seryn_l_artisane_refuser_la_panne', 'Refuser la panne', NULL, '{"nature":"aseryn","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"1 PA, 1/scène","activation":null,"texte_court":"un équipement à ta portée tombe en panne réparable : tu le relances jusqu''à la fin de la scène. Il reste endommagé.","texte_reference":"1/Scène — 1 PA Un équipement que Seryn utilise ou peut immédiatement atteindre devient inutilisable à cause d''une panne ou détérioration réparable. Elle le remet provisoirement en fonctionnement jusqu''à la fin de la scène. Il reste réellement endommagé et devra être réparé ensuite.","lore":"Seryn refuse qu’une panne réparable décide seule du sort de la scène. Elle ramène l’équipement endommagé à un fonctionnement provisoire, bricolage de survie qui laisse intacte la nécessité d’une vraie réparation ensuite.","groupe_actuel":"Traditions des Treize › Seryn — l’Artisane","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'aseryn', 'aseryn_traditions_des_treize_cumulables_sans_taxe_natyel_le_nourricier', 'Natyel, le Nourricier', NULL, '{"nature":"aseryn","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"quatre négations finales coupées."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_natyel_le_nourricier_lire_la_terre', 'Lire la terre', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"quelques minutes","activation":"Quelques minutes d’examen","texte_court":"tu repères les ressources d''un milieu naturel ; +3 pour trouver une ressource rare ou vérifier sa salubrité. Une eau ou un aliment manifestement impropre est reconnu sans test.","texte_reference":"Après quelques minutes d’examen du milieu naturel, vous repérez ses ressources et gagnez +3 pour trouver une ressource difficile ou en vérifier la salubrité. Une eau ou un aliment courant manifestement impropre est reconnu sans test après examen.\n\nPas de révélation automatique d’une substance surnaturelle inconnue ni de nourriture créée.","lore":"La terre parle à Natyel en traces de vie et de ressources. Eau, nourriture, passages de faune et déséquilibres écologiques deviennent lisibles après quelques minutes d’attention à un environnement naturel.","groupe_actuel":"Traditions des Treize › Natyel — le Nourricier","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_natyel_le_nourricier_prelevement_efficace', 'Prélèvement efficace', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"passif","activation":null,"texte_court":"après une chasse ou une collecte réussie, +1 DR pour la quantité ou la qualité (max 5).","texte_reference":"Passif Après une chasse, collecte ou récupération naturelle réussie, comptez DR +1 uniquement pour déterminer la quantité ou la qualité des ressources obtenues, sans dépasser DR 5 et sans accroître les dégâts écologiques.","lore":"Le Nourricier prélève sans gaspiller ce qu’un milieu peut réellement offrir. Une chasse ou une collecte réussie fournit davantage d’usage grâce à la connaissance de la ressource, pas parce que la nature produit soudain plus qu’elle ne possédait.","groupe_actuel":"Traditions des Treize › Natyel — le Nourricier","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_natyel_le_nourricier_la_famille_ne_manque_de_rien', 'La famille ne manque de rien', NULL, '{"nature":"aseryn","cout":3,"cout_actuel":2,"palier":"III","porte":null,"palier_double":null,"acces":"1/scénario","activation":"1/scénario","texte_court":"révèle une préparation antérieure crédible : nourriture, eau et abri simple pour cinq personnes pendant trois jours. Ni argent, ni équipement rare.","texte_reference":"Une fois par scénario, révélez une préparation antérieure crédible assurant nourriture, eau et abri simple à cinq personnes pendant trois jours. Les lieux, réserves et moyens doivent avoir pu être préparés ; aucun argent ni équipement rare n’est créé.\n\nUne vraie rupture de ravitaillement est visée, pas un revenu supplémentaire. Ce talent ne donne pas de munitions spéciales, de véhicule ni de ressource occulte.","lore":"Natyel pense la subsistance avant qu’elle devienne une urgence. Lorsqu’un manque réel apparaît, il peut révéler la réserve ou la solution modeste qu’un Nourricier prudent avait eu une occasion crédible de préparer bien plus tôt.","groupe_actuel":"Traditions des Treize › Natyel — le Nourricier","statut_regle":"correction","changements":"Coût 2 → 3."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'aseryn', 'aseryn_traditions_des_treize_cumulables_sans_taxe_erith_la_sentinelle', 'Erith, la Sentinelle', NULL, '{"nature":"aseryn","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Périmètre réduit de huit phrases à trois, même effet. Ressort face à Je t''avais prévenu (Henael, Angelus) : Erith avertit de ce qu''il a lui-même détecté ; Henael relève de la clairvoyance et coûte 2 Aura."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_erith_la_sentinelle_veille_d_erith', 'Veille d''Erith', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"passif","activation":null,"texte_court":"+3 pour détecter une embuscade, une intrusion ou une approche hostile quand tu surveilles vraiment.","texte_reference":"Passif +3 pour détecter une embuscade, une intrusion ou une approche hostile lorsque le personnage assure réellement une surveillance.","lore":"La veille d’Erith est une discipline active. Quand elle assume réellement la surveillance, changements de rythme, approche hostile et détails d’embuscade reçoivent toute l’attention d’un esprit qui n’est pas distrait par le reste.","groupe_actuel":"Traditions des Treize › Erith — la Sentinelle","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_erith_la_sentinelle_alerte_fulgurante', 'Alerte fulgurante', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Réaction, 1 PA, 1/scène","activation":"Réaction · 1 PA · 1/scène","texte_court":"ton avertissement empêche jusqu''à trois alliés d''être Surpris par le danger que tu viens de détecter. Aucun PA gagné.","texte_reference":"Une fois par scène, pour 1 PA en Réaction, votre avertissement immédiat permet à jusqu’à trois alliés de ne pas être Surpris par le danger que vous venez de détecter. Ils doivent pouvoir recevoir l’alerte et ne gagnent aucun PA.","lore":"Erith sait qu’une alerte n’a de valeur que si elle arrive avant l’impact. Lorsqu’elle détecte la menace la première, son avertissement peut arracher un allié à l’ignorance juste assez tôt pour qu’il ne subisse pas le danger comme une surprise totale.","groupe_actuel":"Traditions des Treize › Erith — la Sentinelle","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_erith_la_sentinelle_perimetre_sous_controle', 'Périmètre sous contrôle', NULL, '{"nature":"aseryn","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"10 minutes","activation":null,"texte_court":"après étude d''un lieu délimité (appartement, étage, petit camp), pour la scène, tu sais aussitôt qu''un changement physique grossier s''y produit, et une intrusion par un accès étudié ne peut te Surprendre par simple Furtivité. Téléportation, accès inconnu ou pouvoir adapté contournent la veille.","texte_reference":"Préparation de 10 minutes Après avoir étudié un lieu raisonnablement délimité — appartement, étage, petit camp, portion d’entrepôt, cour — Erith établit son périmètre pour la scène. Il conserve instinctivement l’état pertinent des accès et zones qu’il a pu intégrer et sait immédiatement qu’un changement physique grossier s’y produit. Une intrusion hostile empruntant un accès ou trajet intégré au périmètre ne peut pas le Surprendre par de simples moyens ordinaires de Furtivité. L’intrus peut rester caché après son entrée et Erith ne connaît pas automatiquement son identité ni sa position précise. Téléportation, passage dimensionnel, accès réellement inconnu, capacité surnaturelle spécifiquement adaptée ou altération du périmètre depuis l’extérieur peuvent contourner la veille.","lore":"Après avoir étudié un lieu, la Sentinelle en garde un modèle vivant. Portes, passages et zones intégrées au périmètre ont pour elle un état attendu ; une intrusion grossière devient donc immédiatement une anomalie, même si l’intrus reste ensuite caché.","groupe_actuel":"Traditions des Treize › Erith — la Sentinelle","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'aseryn', 'aseryn_traditions_des_treize_cumulables_sans_taxe_lisirast_l_archiviste', 'Lisirast, l''Archiviste', NULL, '{"nature":"aseryn","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"fréquence du livre (1/scène) rétablie sur Index vivant, absente du site."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_lisirast_l_archiviste_memoire_d_archive', 'Mémoire d''archive', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"passif","activation":null,"texte_court":"ce que tu choisis d''archiver mentalement revient avec une grande précision. Pas de mémoire totale.","texte_reference":"Passif Ce que Lisirast a volontairement décidé d''archiver mentalement peut être restitué avec une très grande précision. Le Talent n''accorde pas une mémoire eidétique permanente de tout ce qu''il a vécu.","lore":"Une mémoire volontairement archivée n’est pas abandonnée au polissage ordinaire du souvenir. Lisirast la conserve avec une précision méthodique, comme une pièce classée que l’on pourra ressortir sans prétendre avoir enregistré chaque instant de sa vie.","groupe_actuel":"Traditions des Treize › Lisirast — l’Archiviste","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_lisirast_l_archiviste_index_vivant', 'Index vivant', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"1/scène","activation":"Passif","texte_court":"en comparant tes archives à un document, une scène ou un témoignage disponible, tu repères les différences factuelles ; +3 pour en tirer liens ou conclusions.","texte_reference":"Lorsque vous comparez vos archives mémorisées à un document, une scène ou un témoignage réellement disponible, vous repérez les différences factuelles accessibles à cette comparaison. Les tests pour en tirer des liens ou des conclusions bénéficient de +3.\n\nAucun document absent n’est créé et les ressemblances ne prouvent pas automatiquement l’identité d’une personne.","lore":"Les archives deviennent un outil de comparaison plutôt qu’un simple réservoir de souvenirs.","groupe_actuel":"Traditions des Treize › Lisirast — l’Archiviste","statut_regle":"correction","changements":"fréquence du livre (1/scène) rétablie sur Index vivant, absente du site."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_lisirast_l_archiviste_chambre_scellee', 'Chambre scellée', NULL, '{"nature":"aseryn","cout":3,"cout_actuel":2,"palier":"III","porte":null,"palier_double":null,"acces":"passif","activation":"Passif","texte_court":"un secret majeur, compartimenté, échappe à une lecture mentale superficielle ; une fouille ciblée ou une altération de ce secret affronte ta Défense occulte à +3. Un secret à la fois ; une lecture profonde réussie peut le franchir.","texte_reference":"Un secret majeur compartimenté reste inaccessible à une lecture mentale superficielle, même si une question le remet à l’esprit. Une fouille ciblée ou une altération de ce secret rencontre +3 à votre Défense occulte ; un seul secret est protégé à la fois.\n\nLe +3 ne se cumule pas avec une résistance mentale substantiellement équivalente. L’inconscience n’ouvre pas le compartiment ; une lecture profonde réussie peut le franchir.","lore":"Lisirast sait cacher un secret même à l’intérieur de son propre esprit. Il compartimente volontairement cette mémoire derrière une porte mentale que la curiosité superficielle ne rencontre pas et qu’une fouille ciblée doit réellement forcer.","groupe_actuel":"Traditions des Treize › Lisirast — l’Archiviste","statut_regle":"correction","changements":"Coût 2 → 3."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'aseryn', 'aseryn_traditions_des_treize_cumulables_sans_taxe_lisithas_le_juge', 'Lisithas, le Juge', NULL, '{"nature":"aseryn","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"deux talents au palier II."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_lisithas_le_juge_contradiction', 'Contradiction', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R, passif","activation":"Passif · bonus 1/scène","texte_court":"tu repères les contradictions entre déclarations et faits établis. Une fois par scène, en exposer une donne +3 au test social qui s''appuie dessus. Pas un détecteur de mensonge.","texte_reference":"Vous repérez les contradictions entre les déclarations entendues et les faits personnellement établis. Une fois par scène, mettre explicitement une contradiction en évidence donne +3 au test social qui s’appuie directement dessus.\n\nCe n’est pas une détection de mensonge : un interlocuteur peut être sincère et se tromper. Aucun fait extérieur non connu n’est automatiquement révélé.","lore":"Deux affirmations incompatibles sonnent faux à Lisithas même si chacune paraît plausible séparément. Il remarque la contradiction interne au discours, ce qui n’est ni une preuve de mensonge ni la solution d’une enquête plus vaste.","groupe_actuel":"Traditions des Treize › Lisithas — le Juge","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_lisithas_le_juge_plaidoyer_raisonne', 'Plaidoyer raisonné', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R","activation":null,"texte_court":"pour convaincre par des faits, des règles, des contrats ou des engagements, Esprit + Diplomatie au lieu de Charisme + Diplomatie. Ni séduction, ni flatterie.","texte_reference":"V/SR/R Lorsqu''il cherche à convaincre par un raisonnement construit sur des faits, règles, contrats, obligations ou engagements connus, Lisithas peut utiliser Esprit + Diplomatie à la place de Charisme + Diplomatie. Ce Talent ne s''applique pas à la séduction, la flatterie ou l''inspiration purement émotionnelle.","lore":"Lisithas sait convaincre en construisant une chaîne de faits, de règles et d’engagements. Son autorité vient alors de la solidité du raisonnement plutôt que du charme personnel, méthode peu utile lorsque seule l’émotion devrait emporter l’adhésion.","groupe_actuel":"Traditions des Treize › Lisithas — le Juge","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_lisithas_le_juge_arbitrage', 'Arbitrage', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":1,"palier":"II","porte":null,"palier_double":null,"acces":"1/scène","activation":"1/scène","texte_court":"si les parties acceptent ton arbitrage, tu cernes le désaccord et les concessions possibles ; +3 à la Diplomatie pour conclure.","texte_reference":"Une fois par scène, lorsque les parties acceptent votre arbitrage, identifiez le désaccord et les concessions possibles d’après les faits exposés. Vous gagnez +3 au test de Diplomatie visant à conclure ce compromis.\n\nCe bonus ne force ni obéissance ni engagement surnaturel.","lore":"Lisithas arbitre en séparant les positions, les faits et les concessions possibles. Lorsque les deux parties reconnaissent son rôle, il peut faire apparaître le véritable nœud du désaccord sans transformer le jugement en oracle.","groupe_actuel":"Traditions des Treize › Lisithas — le Juge","statut_regle":"correction","changements":"Coût 1 → 2."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_lisithas_le_juge_autorite_du_jugement', 'Autorité du jugement', NULL, '{"nature":"aseryn","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"1 PA, 1/scène ; requiert Plaidoyer raisonné","activation":"1 PA · 1/scène","texte_court":"après un fait ou un raisonnement pertinent, Esprit + Diplomatie contre Volonté + Force Mentale de jusqu''à trois interlocuteurs : ceux que tu bats suspendent l''escalade violente jusqu''au début du round suivant, tant que ton camp respecte la trêve.","texte_reference":"Une fois par scène, après avoir exposé un fait ou raisonnement pertinent, dépensez 1 PA et opposez Esprit + Diplomatie à Volonté + Force Mentale de jusqu’à trois interlocuteurs. Ceux contre lesquels vous réussissez suspendent l’escalade violente jusqu’au début du round suivant, tant que votre camp respecte la même trêve.\n\nCible des êtres capables de comprendre le raisonnement, pas une machine ni une créature sans compréhension pertinente. Ce n’est pas une domination : ils restent libres de se retirer ou de se protéger et ne cèdent aucun autre intérêt.","lore":"Le jugement interrompt l’escalade et ouvre un instant de parole au cœur du conflit.","groupe_actuel":"Traditions des Treize › Lisithas — le Juge","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'aseryn', 'aseryn_traditions_des_treize_cumulables_sans_taxe_selerias_l_aimante', 'Selerias, l''Aimante', NULL, '{"nature":"aseryn","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"fréquence du site (1/round ; livre : 1/scène)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_selerias_l_aimante_lien_entretenu', 'Lien entretenu', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"passif","activation":null,"texte_court":"tu peux Assister une personne avec qui tu as un lien établi même à Compétence 0, si ton aide est un soutien, une connaissance d''elle ou une coordination, pas une expertise.","texte_reference":"Passif Lorsqu''elle aide une personne avec laquelle elle entretient un lien établi, Selerias peut fournir une Assistance fondée sur son soutien, sa connaissance de la personne ou sa coordination même si elle possède 0 dans la Compétence technique concernée, à condition que ce ne soit précisément pas l''expertise technique qui constitue l''aide.","lore":"L’Aimante peut être utile sans connaître le métier de l’autre, précisément parce qu’elle le connaît lui. Soutien, anticipation et coordination deviennent une Assistance valable tant que le problème n’exige pas de sa part l’expertise technique absente.","groupe_actuel":"Traditions des Treize › Selerias — l’Aimante","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_selerias_l_aimante_je_te_connais', 'Je te connais', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Réaction, 1 PA, 1/round","activation":"Réaction · 1 PA · 1/round","texte_court":"Assistance +3 à la résistance d''un proche contre la peur ou une manipulation affective. Lien et communication réels.","texte_reference":"Pour 1 PA en Réaction, une fois par round, apportez une Assistance +3 à la résistance d’un proche contre une peur ou une manipulation affective. Le lien et une communication réelle restent indispensables ; une seule Assistance s’applique.","lore":"Selerias connaît assez un proche pour l’aider à se retrouver lorsqu’une émotion étrangère cherche à le remodeler. Sa voix et leur histoire commune offrent un point fixe contre peur, rupture de confiance ou manipulation affective.","groupe_actuel":"Traditions des Treize › Selerias — l’Aimante","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_selerias_l_aimante_la_famille_tient', 'La famille tient', NULL, '{"nature":"aseryn","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"1 PA, 1/scène","activation":"1 PA · 1/scène","texte_court":"le Stress de jusqu''à trois proches baisse d''un cran, même en combat (Paniqué → Tendu, Tendu → Normal). Ni soin, ni dissipation.","texte_reference":"Une fois par scène, pour 1 PA, réduisez d’un cran le Stress psychologique de jusqu’à trois proches capables de recevoir votre soutien, même pendant le combat. Les minima imposés par les blessures et les effets surnaturels toujours actifs demeurent applicables.\n\nPaniqué devient Tendu et Tendu devient Normal ; ce n’est ni un soin ni une dissipation. Chaque proche doit être réellement lié au personnage.","lore":"Un lien personnel maintient le groupe uni lorsque la peur menace de le disperser.","groupe_actuel":"Traditions des Treize › Selerias — l’Aimante","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'aseryn', 'aseryn_traditions_des_treize_cumulables_sans_taxe_theana_la_guerisseuse', 'Theana, la Guérisseuse', NULL, '{"nature":"aseryn","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"deux talents au palier II."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_theana_la_guerisseuse_il_de_theana', 'Œil de Theana', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":null,"texte_court":"un diagnostic courant de ton domaine se fait sans jet si l''examen est possible ; un cas rare, masqué ou surnaturel donne +3.","texte_reference":"V/SR/R Pour un diagnostic courant dans son domaine, aucun jet n''est nécessaire dès lors qu''un examen réel est possible et que rien ne masque anormalement le problème. Face à un cas rare, complexe, masqué ou surnaturel, +3 au test de diagnostic.","lore":"L’œil de Theana reconnaît sans théâtre ce que son expérience médicale a déjà appris à voir. Les cas courants deviennent évidents à l’examen ; les situations rares ou masquées bénéficient plutôt d’un regard exceptionnellement bien entraîné.","groupe_actuel":"Traditions des Treize › Theana — la Guérisseuse","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_theana_la_guerisseuse_medecine_de_terrain', 'Médecine de terrain', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"passif","activation":null,"texte_court":"ignore jusqu''à −3 dû au lieu, au transport du patient ou à des outils improvisés mais fonctionnels.","texte_reference":"Passif Ignorez jusqu''à -3 de malus circonstanciel provenant d''un lieu inadéquat, du déplacement du patient ou d''outils improvisés mais réellement fonctionnels. Le Talent ne crée jamais un matériel indispensable absent.","lore":"La médecine de terrain consiste à faire correctement avec un lieu mauvais et des outils imparfaits. Theana compense mouvement, improvisation et environnement tant que ce qui est absolument indispensable au soin existe encore vraiment.","groupe_actuel":"Traditions des Treize › Theana — la Guérisseuse","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_theana_la_guerisseuse_geste_salvateur', 'Geste salvateur', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"1/scène","activation":null,"texte_court":"après un échec non narratif en soins d''urgence ou stabilisation, relance le d10e et garde le second.","texte_reference":"1/Scène Après un échec non narratif à un test de soins d''urgence ou de stabilisation, relancez le 1d10e et conservez le second résultat.","lore":"Theana garde dans ses mains la possibilité d’un second geste quand l’urgence médicale vient de mal tourner. Un échec de stabilisation peut être repris immédiatement, comme si l’instinct de la Guérisseuse refusait de laisser le patient à cette première issue.","groupe_actuel":"Traditions des Treize › Theana — la Guérisseuse","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_traditions_des_treize_theana_la_guerisseuse_l_impossible_reste_possible', 'L''impossible reste possible', NULL, '{"nature":"aseryn","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"1/scénario","activation":null,"texte_court":"un acte médical rendu impossible par les seules conditions matérielles se tente à Difficulté 21 (ou sa difficulté normale si elle est plus haute), si l''indispensable est là.","texte_reference":"1/Scénario Un acte médical normalement réalisable serait impossible uniquement à cause des conditions matérielles présentes. Si Theana dispose malgré tout des éléments absolument indispensables, elle peut tenter l''intervention à Difficulté 21, ou à sa difficulté normale si celle-ci est supérieure.","lore":"Pour Theana, des conditions terribles ne rendent pas automatiquement impossible une médecine dont les éléments vitaux sont encore présents. Elle peut tenter l’intervention que d’autres renonceraient à entreprendre, tout en restant soumise à la difficulté réelle du cas.","groupe_actuel":"Traditions des Treize › Theana — la Guérisseuse","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'aseryn', 'aseryn_dratyn_la_maitresse_de_la_foudre', 'Dratyn, la Maîtresse de la Foudre', NULL, '{"nature":"aseryn","chemin":["Dratyn, la Maîtresse de la Foudre"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'aseryn', 'aseryn_dratyn_la_maitresse_de_la_foudre_foudre', 'Foudre', NULL, '{"nature":"aseryn","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun. Voir question 3."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_dratyn_la_maitresse_de_la_foudre_talents_communs_de_dratyn_conduction', 'Conduction', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA sous pression","activation":null,"texte_court":"tu guides, attires, coupes ou répartis un courant existant ; provoques ou empêches un arc ; charges ou vides un objet ; influences un circuit simple. Pas encore ta propre Foudre.","texte_reference":"SR/R — 1 PA sous pression L''Aseryn peut guider, attirer, interrompre ou redistribuer un courant électrique déjà existant : exploiter un conducteur, provoquer ou empêcher un arc, charger ou décharger un objet, influencer un circuit simple. Il ne produit pas encore sa propre Foudre.","lore":"Avant de produire sa propre foudre, l’Aseryn apprend à écouter celle qui existe déjà. Courants, conducteurs et charges deviennent des chemins qu’il peut ouvrir, fermer ou dévier sans confondre cette maîtrise avec la création d’énergie.","groupe_actuel":"Dratyn — la Maîtresse de la Foudre › Talents communs de Dratyn","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_dratyn_la_maitresse_de_la_foudre_talents_communs_de_dratyn_foudre_aseryne', 'Foudre aseryne', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA ; requiert Conduction","activation":null,"texte_court":"tu génères ta Foudre : attaque standard, DGT 7.","texte_reference":"Prérequis : Conduction | R — 1 PA L''Aseryn peut générer et projeter sa propre Foudre. Il gagne l''attaque de Foudre standard, DGT 7, selon les règles communes ci-dessus.","lore":"La Foudre aseryne naît du corps comme une extension naturelle de sa charge intérieure. Elle ne dépend plus d’un câble ou d’un orage extérieur : l’Aseryn devient lui-même la source capable de projeter l’éclair.","groupe_actuel":"Dratyn — la Maîtresse de la Foudre › Talents communs de Dratyn","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_dratyn_la_maitresse_de_la_foudre_talents_communs_de_dratyn_orage_aseryn', 'Orage aseryn', NULL, '{"nature":"aseryn","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 1/scène","activation":null,"texte_court":"une décharge en zone de 3 m de rayon à portée. Un seul Jet de Foudre, comparé à la Défense de chaque cible, DGT 7.","texte_reference":"Prérequis : Foudre aseryne | R — 2 PA — 1/Scène L''Aseryn libère une décharge dans une zone de 3 m de rayon à portée. Un seul Jet de Foudre est comparé individuellement à la Défense de chaque cible. DGT 7.","lore":"L’Orage aseryn cesse de choisir une seule trajectoire. La charge éclate dans une petite zone et cherche chaque corps séparément, comme si un nuage de tempête avait été comprimé à hauteur d’homme puis ouvert d’un coup.","groupe_actuel":"Dratyn — la Maîtresse de la Foudre › Talents communs de Dratyn","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'aseryn', 'aseryn_dratyn_la_maitresse_de_la_foudre_arc', 'Arc', NULL, '{"nature":"aseryn","forme":"une_porte","forme_lot":"collection à une porte (requiert Foudre aseryne)","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"deux talents au palier II. **Correction** : prérequis Foudre aseryne de Paratonnerre rétabli (livre V6 ; absent du site). Les exemples de décharges sont une précision de lecture, pas un élargissement (le rapport proposait d''y ajouter les armes à énergie et un bonus de DGT : non appliqué)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_dratyn_la_maitresse_de_la_foudre_talents_communs_de_dratyn_decharge_maitrisee', 'Décharge maîtrisée', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R","activation":null,"texte_court":"tu doses intensité et durée : alimenter ou vider un appareil, choc non létal, couper une installation ordinaire, souder ou brûler un conducteur. Jet de Foudre si incertain.","texte_reference":"Prérequis : Foudre aseryne | R L''Aseryn sait moduler intensité et durée : alimenter ou décharger un appareil, provoquer un choc non destiné à tuer, neutraliser une installation électrique ordinaire accessible, souder ou brûler localement un matériau conducteur, etc. En cas d''incertitude, utilisez un Jet de Foudre contre une difficulté appropriée.","lore":"Une fois la foudre acquise, Dratyn enseigne à ne pas tout résoudre par la violence maximale. Intensité et durée deviennent assez fines pour alimenter, neutraliser, souder ou provoquer un choc contrôlé avec le même phénomène qui sert au combat.","groupe_actuel":"Dratyn — la Maîtresse de la Foudre › Talents communs de Dratyn","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_dratyn_la_maitresse_de_la_foudre_talents_communs_de_dratyn_paratonnerre', 'Paratonnerre', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, Réaction, 1 PA, 1/round","activation":"Réaction · 1 PA · 1/round","texte_court":"une décharge électrique (Foudre, taser, arme à arc électrique…) vise toi ou un allié à 5 m : Jet de Foudre contre son attaque ; réussite, elle est détournée vers un conducteur ou une zone sûre. Jamais renvoyée sur un adversaire.","texte_reference":"Une fois par round, pour 1 PA en Réaction, opposez votre Jet de Foudre à une décharge électrique visant vous-même ou un allié situé à 5 m maximum. En réussite, détournez-la vers un conducteur ou une zone sûre accessible, sans la renvoyer gratuitement sur un adversaire.\n\nL’intervention est annoncée avant résolution ; on ne relance pas rétroactivement une défense déjà ratée. Une zone ne perd que l’exposition de la cible effectivement protégée, pas tous ses effets sur les autres.","lore":"Le Paratonnerre transforme l’Aseryn en chemin volontaire pour une décharge qui allait le frapper. Il saisit la logique du courant et la conduit vers un point sûr ou conducteur, sans faire de cette défense un renvoi automatique contre l’assaillant.","groupe_actuel":"Dratyn — la Maîtresse de la Foudre › Talents communs de Dratyn","statut_regle":"correction","changements":"deux talents au palier II. **Correction** : prérequis Foudre aseryne de Paratonnerre rétabli (livre V6 ; absent du site). Les exemples de décharges sont une précision de lecture, pas un élargissement (le rapport proposait d''y ajouter les armes à énergie et un bonus de DGT : non appliqué)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_dratyn_la_maitresse_de_la_foudre_talents_communs_de_dratyn_arc_en_chaine', 'Arc en chaîne', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1/scène","activation":null,"texte_court":"après un Jet de Foudre réussi, une seconde cible à 3 m de la première est frappée par le même résultat (elle se défend), DGT 5. Un seul rebond.","texte_reference":"Prérequis : Foudre aseryne | R — 1/Scène Après un Jet de Foudre réussi contre une cible, une seconde cible située à 3 m maximum de la première peut être frappée par le même résultat. Elle se défend normalement. La seconde décharge est DGT 5. Un seul rebond.","lore":"Après le premier impact, Dratyn peut laisser un reste de charge chercher une seconde présence proche. L’arc ne devient pas une tempête autonome : il bondit une seule fois, prolongement affaibli mais encore dangereux de la décharge initiale.","groupe_actuel":"Dratyn — la Maîtresse de la Foudre › Talents communs de Dratyn","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'aseryn', 'aseryn_dratyn_la_maitresse_de_la_foudre_specialisation_de_foudre_une_seule', 'Spécialisation de Foudre (une seule)', NULL, '{"nature":"aseryn","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"deux talents au palier II. Coût en PA du site (1 ; livre : 2 PA). Voir question 4."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_dratyn_la_maitresse_de_la_foudre_specialisation_de_foudre_createur_foudre_originelle_foudre_originelle', 'Foudre originelle', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R","activation":null,"texte_court":"à volonté, ta Foudre devient originelle : DGT 9, et la magie active devient une cible valide (mur magique, élémentaire maintenu, familier de magie, protection de Mageius…).","texte_reference":"Prérequis : Foudre aseryne + enseignement du Créateur | R Lorsque le personnage le souhaite, ses attaques de Foudre deviennent originelles : DGT 9. La magie active et ses constructions deviennent des cibles valides : mur magique, manifestation élémentaire maintenue, familier constitué de magie, protection de Mageius, etc.","lore":"Cette foudre remonte à une expression plus ancienne que les simples arcs électriques. Elle brûle le monde physique, mais sait aussi trouver un mur de sort, un familier constitué de magie ou une protection de Mageius comme s’ils possédaient leur propre conductivité.","groupe_actuel":"Dratyn — la Maîtresse de la Foudre › Spécialisation de Foudre › Créateur — Foudre originelle","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_dratyn_la_maitresse_de_la_foudre_specialisation_de_foudre_createur_foudre_originelle_brise_magie', 'Brise-magie', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA","activation":null,"texte_court":"Jet de Foudre contre le résultat de lancement d''un effet magique actif (sinon 15 / 18 / 21 / 25 selon sa puissance) : un effet temporaire ou maintenu est détruit ; un enchantement permanent, un lieu ou un artefact majeur est au mieux neutralisé pour la scène.","texte_reference":"Prérequis : Foudre originelle | R — 1 PA L''Aseryn vise directement un effet magique actif. Effectuez un Jet de Foudre contre son résultat de lancement s''il est connu, sinon contre une difficulté 15 / 18 / 21 / 25 selon sa puissance. En réussite, un effet temporaire ou maintenu est détruit. Un enchantement permanent, un lieu magique ou un artefact majeur n''est au mieux neutralisé pour la scène que si sa nature permet réellement une interruption.","lore":"La Foudre originelle de Dratyn reconnaît la magie comme une structure conductrice à briser. Au lieu de chercher une chair, la décharge s’accroche au sort actif et tente d’en disperser l’architecture.","groupe_actuel":"Dratyn — la Maîtresse de la Foudre › Spécialisation de Foudre › Créateur — Foudre originelle","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_dratyn_la_maitresse_de_la_foudre_specialisation_de_foudre_createur_foudre_originelle_deferlement_originel', 'Déferlement originel', NULL, '{"nature":"aseryn","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 1/scène","activation":null,"texte_court":"une attaque de Foudre originelle à DGT 13 ; les Protections d''origine magique ne réduisent rien. Contre une manifestation magique, le même jet sert aussi de Brise-magie.","texte_reference":"Prérequis : Brise-magie | R — 2 PA — 1/Scène Une attaque de Foudre originelle passe à DGT 13. Les Protections d''origine magique ne réduisent pas ses dégâts. Si la cible est elle-même une manifestation magique, le résultat du Jet peut également servir à la briser selon Brise-magie, sans second jet.","lore":"Quand Dratyn libère toute la violence de la Foudre originelle, protections et constructions magiques deviennent elles-mêmes matière à l’impact. La décharge frappe assez profondément pour blesser la cible et défaire, dans le même mouvement, ce qui était fait de magie.","groupe_actuel":"Dratyn — la Maîtresse de la Foudre › Spécialisation de Foudre › Créateur — Foudre originelle","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_dratyn_la_maitresse_de_la_foudre_specialisation_de_foudre_esprit_noire_foudre_noire_foudre', 'Noire-Foudre', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R","activation":null,"texte_court":"ta décharge devient presque invisible et ne trahit pas ta position. Elle touche esprits, Ombres et créatures immatérielles (contre une cible purement immatérielle : sa Défense et sa Protection occultes).","texte_reference":"Prérequis : Foudre aseryne + enseignement de l’Esprit | R La décharge devient presque invisible et ne révèle pas automatiquement la position de son utilisateur par un éclair lumineux. Elle peut affecter normalement les esprits, Ombres et créatures immatérielles ; contre une cible purement immatérielle, utilisez sa Défense occulte et sa Protection occulte plutôt que l''armure physique.","lore":"La Noire-Foudre ressemble moins à un éclair qu’à une absence brusque de lumière dans le trajet de la décharge. Sa discrétion n’est qu’un effet secondaire : sa vraie singularité est d’être chez elle parmi Ombres, esprits et formes sans chair.","groupe_actuel":"Dratyn — la Maîtresse de la Foudre › Spécialisation de Foudre › Esprit — Noire-Foudre","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_dratyn_la_maitresse_de_la_foudre_specialisation_de_foudre_esprit_noire_foudre_atteindre_l_immateriel', 'Atteindre l''immatériel', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R","activation":"Passif","texte_court":"ta Noire-Foudre traverse les obstacles purement matériels, même un couvert total, vers une cible immatérielle réellement perçue à portée.","texte_reference":"La Noire-Foudre peut traverser les obstacles purement matériels, même un couvert total, pour atteindre une cible immatérielle réellement perçue à portée normale. Les protections spirituelles ou spécialement adaptées restent applicables.\n\nPas de tir aveugle, de nouvelle détection ni d’allongement automatique des 20 m de portée.","lore":"La Noire-Foudre ne s’arrête pas devant une cloison qui n’existe que pour la matière. Si l’esprit visé est réellement perçu, la décharge suit sa présence immatérielle plutôt que le béton, le métal ou l’armure qu’un corps physique aurait utilisés.","groupe_actuel":"Dratyn — la Maîtresse de la Foudre › Spécialisation de Foudre › Esprit — Noire-Foudre","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_dratyn_la_maitresse_de_la_foudre_specialisation_de_foudre_esprit_noire_foudre_fulguration_spirituelle', 'Fulguration spirituelle', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1/scène","activation":null,"texte_court":"tu vises la part immatérielle d''un être quand elle est exposée (possession, projection astrale, forme spirituelle, pouvoir mental maintenu) : contre sa Défense occulte, sans Protection matérielle. Dégâts en PV normaux.","texte_reference":"Prérequis : Noire-Foudre | R — 1/Scène L''Aseryn peut viser la composante immatérielle d''un être seulement lorsque celle-ci est réellement exposée ou activement engagée : possession, projection astrale, forme spirituelle, pouvoir mental maintenu ou phénomène comparable. L''attaque est alors opposée à la Défense occulte et ignore les Protections purement matérielles. Les dégâts restent des PV normaux.","lore":"Dratyn apprend à viser non le corps, mais la part spirituelle momentanément exposée par une possession, une projection ou un pouvoir mental maintenu. La fulguration traverse alors les défenses matérielles pour heurter ce qui agit réellement derrière elles.","groupe_actuel":"Dratyn — la Maîtresse de la Foudre › Spécialisation de Foudre › Esprit — Noire-Foudre","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_dratyn_la_maitresse_de_la_foudre_specialisation_de_foudre_esprit_noire_foudre_eclipse_noire', 'Éclipse noire', NULL, '{"nature":"aseryn","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 1/scène ; requiert Fulguration spirituelle","activation":"2 PA · 1/scène","texte_court":"jusqu''à trois créatures immatérielles ou effets métaphysiques temporaires perçus. Un Jet de Foudre comparé à chacun : les créatures subissent DGT 9, les effets vaincus se dissipent.","texte_reference":"Pour 2 PA, une fois par scène, ciblez jusqu’à trois créatures immatérielles ou effets métaphysiques temporaires réellement perçus à portée. Un même Jet de Foudre est comparé à chaque Défense ou Puissance : les créatures subissent DGT 9 et les effets temporaires vaincus sont dissipés.\n\nChaque cible occupe un emplacement. Aucun cumul de dégâts et de suppression de l’existence sur une créature : elle conserve ses PV. Les protections spirituelles pertinentes s’appliquent ; les composantes d’un être incarné doivent être effectivement exposées selon Fulguration spirituelle.","lore":"La Noire-Foudre se divise entre plusieurs présences spirituelles ou effets métaphysiques.","groupe_actuel":"Dratyn — la Maîtresse de la Foudre › Spécialisation de Foudre › Esprit — Noire-Foudre","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_dratyn_la_maitresse_de_la_foudre_specialisation_de_foudre_erosion_foudre_vaporeuse_foudre_vaporeuse', 'Foudre vaporeuse', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R","activation":"Sur une attaque réussie","texte_court":"sacrifie 2 points de dégâts d''un coup réussi (avant réduction) : une Armure ou Protection matérielle touchée perd 2 (jamais sous 0) jusqu''à la fin de la scène. Une fois par couche.","texte_reference":"En sacrifiant 2 points de dégâts d’un coup réussi avant réduction, diminuez de 2, sans passer sous 0, une Armure ou Protection matérielle directement touchée jusqu’à la fin de la scène. Une même couche ne subit cet effet qu’une fois ; Ruine des protections remplace −2 par −3, sans addition.\n\nRuine conserve l’ouverture aux protections surnaturelles immatérielles. L’armure attaquée peut être érodée même si elle ne protégeait pas de la Foudre : l’intérêt peut être d’aider les autres attaquants.","lore":"La Foudre vaporeuse laisse derrière elle moins une brûlure qu’une usure. Protection, armure ou barrière directement frappée se délite, comme si la décharge avait arraché une couche de cohésion destinée à ne pas revenir avant la fin de l’affrontement.","groupe_actuel":"Dratyn — la Maîtresse de la Foudre › Spécialisation de Foudre › Érosion — Foudre vaporeuse","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_dratyn_la_maitresse_de_la_foudre_specialisation_de_foudre_erosion_foudre_vaporeuse_eroder_l_affliction', 'Éroder l''affliction', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA","activation":"1 PA","texte_court":"Jet de Foudre contre le résultat d''origine d''une affliction occulte active (sinon 15 / 18 / 21 / 25) : pour la scène, son malus baisse de 3 et sa difficulté de résistance d''un niveau. Ne touche pas à la Corruption.","texte_reference":"Pour 1 PA, un Jet de Foudre réussi contre une affliction occulte active atténue ses effets pour la scène : malus réduit de 3 et difficulté de résistance abaissée d’un niveau lorsqu’ils existent. Cela ne retire aucun point de Corruption et ne supprime ni Nature ni lien fondamental.\n\nLa jauge de Corruption reste inchangée.\n\nJet de Foudre contre le résultat d’origine de l’affliction, ou contre 15 / 18 / 21 / 25 selon sa puissance. L’effet n’est pas nécessairement guéri.","lore":"L’Érosion peut cibler une affliction plutôt que celui qui la porte. La Foudre vaporeuse travaille sur la malédiction, la corruption ou la maladie surnaturelle comme sur une matière friable, diminuant son emprise sans prétendre avoir déjà guéri sa victime.","groupe_actuel":"Dratyn — la Maîtresse de la Foudre › Spécialisation de Foudre › Érosion — Foudre vaporeuse","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_dratyn_la_maitresse_de_la_foudre_specialisation_de_foudre_erosion_foudre_vaporeuse_ruine_des_protections', 'Ruine des protections', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R","activation":null,"texte_court":"ta Foudre vaporeuse retire 3 au lieu de 2, et peut toucher une Protection surnaturelle sans matière.","texte_reference":"Prérequis : Foudre vaporeuse | R La réduction de Protection de Foudre vaporeuse passe de -2 à -3 et peut affecter une Protection issue d''un pouvoir surnaturel même sans matérialité physique.","lore":"En approfondissant l’Érosion, l’Aseryn ne distingue plus une plaque d’acier d’une protection surnaturelle par principe. Toute défense qui possède une cohérence propre peut être rongée lorsque la Foudre vaporeuse trouve réellement son point d’appui.","groupe_actuel":"Dratyn — la Maîtresse de la Foudre › Spécialisation de Foudre › Érosion — Foudre vaporeuse","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_dratyn_la_maitresse_de_la_foudre_specialisation_de_foudre_erosion_foudre_vaporeuse_reduire_en_poussiere', 'Réduire en poussière', NULL, '{"nature":"aseryn","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1/scène ; requiert Éroder l''affliction","activation":"Après un Jet de Foudre · 1/scène","texte_court":"après un Jet de Foudre réussi contre la Puissance d''un effet occulte actif, il est détruit s''il est temporaire, suspendu pour la scène s''il est durable et interruptible. Jamais une créature, une Nature ou un lien fondamental ; la Corruption ne bouge pas.","texte_reference":"Après un Jet de Foudre réussi contre la Puissance d’un effet occulte actif, une fois par scène, détruisez cet effet s’il est temporaire ou suspendez-le pour la scène s’il est durable et interruptible. Une créature dotée de PV, sa Nature et les liens fondamentaux ne sont pas des effets supprimables de cette manière.\n\nAucune réussite gratuite : le jet et son coût normal doivent être résolus. Ne modifie pas la jauge de Corruption.\n\nLes effets primordiaux ou explicitement indestructibles restent hors de portée.","lore":"Une altération déjà suffisamment érodée peut finalement perdre sa capacité à se maintenir. L’Aseryn pousse la dégradation jusqu’au seuil où la malédiction, la protection ou la manifestation doit s’effondrer au lieu de seulement s’affaiblir.","groupe_actuel":"Dratyn — la Maîtresse de la Foudre › Spécialisation de Foudre › Érosion — Foudre vaporeuse","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_dratyn_la_maitresse_de_la_foudre_specialisation_de_foudre_fin_foudre_du_silence_foudre_du_silence', 'Foudre du Silence', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R","activation":null,"texte_court":"ta décharge ne fait presque ni tonnerre ni crépitement, DGT 7. Hors attaque, tu graves, sectionnes ou effaces de toutes petites quantités de matière avec une précision extrême.","texte_reference":"Prérequis : Foudre aseryne + enseignement de la Fin | R La décharge ne produit pratiquement ni tonnerre ni crépitement. DGT 7. Hors attaque, l''Aseryn peut appliquer son effet d''effacement avec une extrême précision pour graver, sectionner ou supprimer de très petites quantités de matière sans ravager ce qui les entoure, lorsque la fiction le permet.","lore":"La Foudre du Silence est presque muette parce qu’une part de ce qu’elle touche est simplement retranchée. Employée avec finesse, cette même logique permet de sectionner ou d’effacer une quantité minuscule de matière sans ravager tout ce qui l’entoure.","groupe_actuel":"Dratyn — la Maîtresse de la Foudre › Spécialisation de Foudre › Fin — Foudre du Silence","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_dratyn_la_maitresse_de_la_foudre_specialisation_de_foudre_fin_foudre_du_silence_trace_du_neant', 'Trace du Néant', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R","activation":null,"texte_court":"les dégâts de ta Foudre du Silence ne se régénèrent pas surnaturellement avant la fin de la scène. Contre un Fléau ou son engeance, cela atteint aussi ce qui le fait persister.","texte_reference":"Prérequis : Foudre du Silence | R Les dégâts infligés par la Foudre du Silence ne peuvent pas être récupérés par une Régénération surnaturelle avant la fin de la scène. Contre un Fléau ou une engeance directement issue d''un Fléau, cette propriété affecte réellement les mécanismes qui lui permettent de persister.","lore":"Une plaie laissée par le Silence ne se referme pas surnaturellement comme une blessure ordinaire. Le Néant a touché l’endroit, et les forces qui reconstruisent d’habitude la chair ou les engeances d’un Fléau n’y trouvent plus immédiatement de prise.","groupe_actuel":"Dratyn — la Maîtresse de la Foudre › Spécialisation de Foudre › Fin — Foudre du Silence","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_dratyn_la_maitresse_de_la_foudre_specialisation_de_foudre_fin_foudre_du_silence_trait_du_silence', 'Trait du Silence', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA, 1/scène","activation":"1 PA · 1/scène","texte_court":"un trait DGT 9 qui divise par deux la Protection électrique (arrondi inférieur). Si la marge le permet, il vise un composant précis.","texte_reference":"Pour 1 PA, une fois par scène, projetez un Trait du Silence de DGT 9 divisant par deux la Protection électrique applicable, arrondie à l’inférieur. La précision permet d’atteindre un composant lorsque la marge et la situation l’autorisent, jamais d’effacer automatiquement un organe.","lore":"Le Trait du Silence concentre la Fin dans une ligne assez fine pour chercher une pièce plutôt qu’une masse. Blindage électrique et matière sont forcés de composer avec une attaque qui veut retrancher précisément ce qu’elle a réussi à atteindre.","groupe_actuel":"Dratyn — la Maîtresse de la Foudre › Spécialisation de Foudre › Fin — Foudre du Silence","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_dratyn_la_maitresse_de_la_foudre_specialisation_de_foudre_fin_foudre_du_silence_fin_veritable', 'Fin véritable', NULL, '{"nature":"aseryn","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, passif ; requiert Trace du Néant et Trait du Silence","activation":null,"texte_court":"quand un Fléau ou son engeance subit ta Foudre du Silence dans des conditions qui permettraient sa destruction, régénération, reconstitution, retour ou transfert ne suffisent plus à le sauver. Ne rend pas vulnérable un Fléau majeur.","texte_reference":"Prérequis : Trace du Néant + Trait du Silence | R — Passif Lorsqu''un Fléau ou une de ses engeances subit de la Foudre du Silence et remplit les conditions qui permettraient réellement sa destruction, ses mécanismes habituels de régénération, reconstitution, retour depuis des restes, transfert dans une autre enveloppe ou survie par simple persistance surnaturelle ne suffisent pas automatiquement à l''en sauver. Le Talent ne contourne jamais les conditions narratives nécessaires pour rendre un Fléau majeur vulnérable.","lore":"La Fin ne se contente pas de blesser ce qui devrait un jour disparaître. Lorsqu’un Fléau a enfin été rendu réellement vulnérable, la trace du Silence l’empêche de transformer sa vieille persistance en échappatoire automatique.","groupe_actuel":"Dratyn — la Maîtresse de la Foudre › Spécialisation de Foudre › Fin — Foudre du Silence","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'aseryn', 'aseryn_conseil_de_la_foudre', 'Conseil de la Foudre', NULL, '{"nature":"aseryn","chemin":["Conseil de la Foudre"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'aseryn', 'aseryn_conseil_de_la_foudre_voie_des_ancetres', 'Voie des Ancêtres', NULL, '{"nature":"aseryn","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"deux talents au palier I ; Nom des Ancêtres, « technique commune » du Conseil, prend place ici. Le rapport proposait de fusionner Conseil des morts avec Planification supérieure (Angelus) : refusé. Ressort propre : il faut un vrai accès aux Ancêtres (lieu, communauté, esprits coopératifs)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_conseil_de_la_foudre_technique_commune_nom_des_ancetres', 'Nom des Ancêtres', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":null,"texte_court":"Esprit + Connaissance adaptée identifie un esprit lié au Conseil par son comportement, son langage, ses souvenirs et ses rites ; +3 si c''est un Ancêtre de ta communauté.","texte_reference":"V/SR/R Le personnage a été formé aux généalogies, récits et identités spirituelles du Conseil. Lorsqu''un esprit lié au Conseil se présente, Esprit + Connaissance appropriée permet de l''identifier par son comportement, son langage, ses souvenirs exprimés et les rites qui lui sont associés ; +3 s''il s''agit d''un Ancêtre officiellement conservé par sa propre communauté.","lore":"Le Conseil enseigne les morts comme une lignée encore présente, pas comme un catalogue abstrait. Noms, récits, habitudes et rites permettent à l’Aseryn de reconnaître quel Ancêtre lui parle lorsque sa communauté en a conservé la mémoire.","groupe_actuel":"Conseil de la Foudre › Technique commune","statut_regle":"correction","changements":"deux talents au palier I ; Nom des Ancêtres, « technique commune » du Conseil, prend place ici. Le rapport proposait de fusionner Conseil des morts avec Planification supérieure (Angelus) : refusé. Ressort propre : il faut un vrai accès aux Ancêtres (lieu, communauté, esprits coopératifs)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_conseil_de_la_foudre_voie_des_ancetres_ecouter_les_ancetres', 'Écouter les Ancêtres', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"rituel","activation":null,"texte_court":"auprès d''un esprit du Conseil accessible, demande conseil sur ce qu''il a pu connaître. Le MJ répond selon son savoir et son regard ; aucun esprit n''est omniscient.","texte_reference":"Rituel Auprès d''un esprit du Conseil auquel le personnage a réellement accès, il peut demander conseil sur un sujet que cet Ancêtre a pu connaître ou comprendre. Le MJ répond selon les connaissances, la personnalité et le point de vue du mort ; aucun esprit n''est omniscient.","lore":"Écouter les Ancêtres consiste à demander aux morts ce qu’ils peuvent réellement savoir. La réponse porte leur caractère, leurs souvenirs et parfois leurs angles morts, parce que mourir n’a jamais rendu quelqu’un omniscient.","groupe_actuel":"Conseil de la Foudre › Voie des Ancêtres","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_conseil_de_la_foudre_voie_des_ancetres_memoire_empruntee', 'Mémoire empruntée', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"1/scène ; requiert Écouter les Ancêtres","activation":"Communion · 1/scène","texte_court":"après communion avec un Ancêtre compétent, +3 aux tests d''une Compétence de son expérience jusqu''à la fin de la scène. Une à la fois.","texte_reference":"Après communion avec un Ancêtre compétent, choisissez une Compétence correspondant à son expérience et bénéficiez de +3 à ses tests jusqu’à la fin de la scène. Aucun pouvoir, prérequis biologique ou savoir secret absent de cet Ancêtre n’est obtenu.\n\nUne compétence et une communion préparée actives à la fois. Pas d’empilement avec un bonus équivalent de l’Ancêtre.\n\nUne communion par scène.","lore":"Une communion préparée laisse l’expérience du mort accompagner une discipline pendant toute la scène.","groupe_actuel":"Conseil de la Foudre › Voie des Ancêtres","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_conseil_de_la_foudre_voie_des_ancetres_conseil_des_morts', 'Conseil des morts', NULL, '{"nature":"aseryn","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"1/scénario ; requiert Mémoire empruntée","activation":"Préparation rituelle · 1/scénario","texte_court":"plusieurs Ancêtres consultés aident à préparer une opération : jusqu''à cinq participants briefés relancent chacun un échec non narratif lié au plan pendant l''exécution.","texte_reference":"Une fois par scénario, plusieurs Ancêtres réellement consultés aident à préparer une opération précise. Jusqu’à cinq participants briefés peuvent chacun relancer un échec non narratif directement lié à ce plan pendant sa scène d’exécution, en conservant le second résultat.\n\nUne seule relance de talent par test. Le plan est fixé avant l’action : aucune prévision omnisciente ni possibilité de le redéfinir après l’échec pour englober n’importe quel jet.","lore":"Les Ancêtres confrontent leurs expériences pour préparer les vivants à une opération précise.","groupe_actuel":"Conseil de la Foudre › Voie des Ancêtres","statut_regle":"correction","changements":"deux talents au palier I ; Nom des Ancêtres, « technique commune » du Conseil, prend place ici. Le rapport proposait de fusionner Conseil des morts avec Planification supérieure (Angelus) : refusé. Ressort propre : il faut un vrai accès aux Ancêtres (lieu, communauté, esprits coopératifs)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'aseryn', 'aseryn_conseil_de_la_foudre_voie_du_vaisseau', 'Voie du Vaisseau', NULL, '{"nature":"aseryn","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"**correction** — la phrase « le rang emprunté est plafonné à 6 » était écrite deux fois. Signal : ce plafond de 6 est à vérifier contre le maximum des Compétences."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_conseil_de_la_foudre_voie_du_vaisseau_accueil_du_mort', 'Accueil du mort', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, rituel","activation":null,"texte_court":"tu sers volontairement de Vaisseau à un Ancêtre consentant. Il perçoit et parle par toi sans prendre le contrôle. Hors d''un lieu sûr, une scène au plus.","texte_reference":"SR/R — Rituel Le personnage peut servir volontairement de Vaisseau à un Ancêtre consentant. Il reste conscient ; l''Ancêtre peut percevoir et parler à travers lui sans prendre automatiquement le contrôle du corps. Hors d''un lieu rituellement sûr, la possession dure au maximum une scène sauf ancrage exceptionnel établi par le scénario.","lore":"Le Vaisseau offre volontairement sa chair comme lieu d’accueil à un Ancêtre consentant. Deux consciences partagent alors la même enveloppe sans que le mort devienne automatiquement maître des gestes du vivant.","groupe_actuel":"Conseil de la Foudre › Voie du Vaisseau","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_conseil_de_la_foudre_voie_du_vaisseau_main_de_l_ancetre', 'Main de l''Ancêtre', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"1/round pendant la possession ; requiert Accueil du mort","activation":"Possession coopérative · 1/round","texte_court":"+3 à une action de son expertise. À Compétence 0, il te guide pour une action de connaissance, de procédure ou de coordination. PA dû.","texte_reference":"Pendant une possession coopérative, une fois par round, l’Ancêtre apporte +3 à une action relevant de son expertise. À Compétence 0, son guidage permet une action de connaissance, de procédure ou de coordination, sans prêter de capacité physique absente.\n\nLe PA de l’action reste dû ; aucun tour d’Ancêtre indépendant. Pas de deuxième +3 équivalent sur le même test.","lore":"Le mort guide le geste qu’il connaît sans donner au corps une seconde réserve d’actions.","groupe_actuel":"Conseil de la Foudre › Voie du Vaisseau","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_conseil_de_la_foudre_voie_du_vaisseau_laisser_la_place', 'Laisser la place', NULL, '{"nature":"aseryn","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"1/scène ; requiert Main de l''Ancêtre","activation":"Possession coopérative · 1/scène","texte_court":"l''Ancêtre pilote ton corps jusqu''à la fin de la scène. Pour ses expertises, prends le meilleur de ton rang et du sien (plafonné à 6). Attributs, PV, PA et Talents restent les tiens ; tu peux reprendre le contrôle. Son profil est fixé avec le MJ à l''avance. Pas de +3 de Main ou de Mémoire en plus.","texte_reference":"Une fois par scène, laissez un Ancêtre consentant piloter le corps jusqu’à la fin de la scène : pour ses expertises, utilisez le meilleur de votre rang et du sien, le rang emprunté étant plafonné à 6. Vos Attributs, PV, PA, Talents et limites physiques restent les vôtres ; vous pouvez reprendre le contrôle.\n\nL’Ancêtre doit avoir un profil fixé avec le MJ avant emploi. Aucun Talent surnaturel ni ressource propre de l’Ancêtre n’est prêté. Pour un test utilisant son rang emprunté, Main de l’Ancêtre et Mémoire empruntée ne rajoutent pas +3 : l’emprunt remplace leur guidage. Le rang emprunté est plafonné à 6.","lore":"L’Ancêtre prête son expertise au corps vivant sans lui imposer une autre Nature.","groupe_actuel":"Conseil de la Foudre › Voie du Vaisseau","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'aseryn', 'aseryn_conseil_de_la_foudre_voie_du_gardien_de_la_grotte', 'Voie du Gardien de la Grotte', NULL, '{"nature":"aseryn","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"phrase sur le PA de Défense clarifiée. Fréquence du site (1/round ; livre : 1/scène)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_conseil_de_la_foudre_voie_du_gardien_de_la_grotte_sens_des_morts', 'Sens des morts', NULL, '{"nature":"aseryn","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, passif","activation":null,"texte_court":"tu perçois un esprit désincarné ou une possession active à proximité ; Esprit + Perception pour affiner.","texte_reference":"SR/R — Passif Le personnage perçoit la présence immédiate d''un esprit désincarné ou d''une possession active à proximité. Il ne connaît pas automatiquement l''identité, les intentions ou la position exacte derrière un obstacle. Esprit + Perception permet d''affiner la localisation ou l''état.","lore":"Les morts ont pour le Gardien une présence différente du silence ordinaire. Une désincarnation ou une possession active trouble immédiatement son environnement spirituel, sans lui livrer pour autant le nom ni l’intention de ce qui se tient là.","groupe_actuel":"Conseil de la Foudre › Voie du Gardien de la Grotte","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_conseil_de_la_foudre_voie_du_gardien_de_la_grotte_fermer_la_porte', 'Fermer la porte', NULL, '{"nature":"aseryn","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Réaction, 1 PA, 1/round ; requiert Sens des morts","activation":"Réaction · 1 PA · 1/round","texte_court":"Assistance +3 à la résistance d''une créature à 10 m contre une possession ou une intrusion spirituelle. Si la cible, c''est toi : +3 direct, et ce PA tient lieu de ta Défense active.","texte_reference":"Une fois par round, pour 1 PA en Réaction, accordez Assistance +3 à la résistance d’une créature à 10 m contre une possession ou une intrusion spirituelle. Si vous êtes la cible, appliquez directement +3 à votre résistance ; le PA dépensé est celui de votre Défense active, pas un second PA.\n\nUne seule Assistance et pas de cumul avec une protection substantiellement équivalente. L’effet doit pouvoir être perçu ; il ne dissipe pas une possession déjà établie, rôle d’Expulsion rituelle.","lore":"Fermer la porte revient à renforcer la frontière d’une âme au moment où quelque chose tente de la franchir. Le Gardien transmet ce réflexe de clôture à un proche, ou le resserre autour de lui-même lorsqu’il est visé.","groupe_actuel":"Conseil de la Foudre › Voie du Gardien de la Grotte","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'aseryn', 'aseryn_conseil_de_la_foudre_voie_du_gardien_de_la_grotte_expulsion_rituelle', 'Expulsion rituelle', NULL, '{"nature":"aseryn","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, 2 PA sous pression ; requiert Fermer la porte","activation":null,"texte_court":"sur une personne possédée, Volonté + Maîtrise spirituelle + 1d10e contre la Défense occulte ou la résistance de l''entité. Réussite : l''esprit quitte l''hôte, sans être détruit ni banni.","texte_reference":"Prérequis : Fermer la porte | SR/R — 2 PA sous pression Sur une personne possédée, Volonté + Maîtrise spirituelle + 1d10e contre la Défense occulte ou la résistance de l''entité. En réussite, l''esprit est forcé de quitter l''hôte. Il n''est ni détruit, ni banni définitivement, ni automatiquement renvoyé à la Grotte.","lore":"Le Gardien de la Grotte sait où couper le lien qui permet à un esprit d’habiter un autre corps. L’expulsion rend l’hôte à lui-même, sans prétendre détruire l’intrus ni décider où celui-ci ira ensuite.","groupe_actuel":"Conseil de la Foudre › Voie du Gardien de la Grotte","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
